INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Fundamentação científica de viés positivista.', @q), ('B', N'Convenção social de orientação normativa.', @q), ('C', N'Transgressão comportamental religiosa.', @q), ('D', N'Racionalidade de caráter pragmático.', @q), ('E', N'Inclinação de natureza passional.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Filosofia' AND t.nome = N'Teoria do conhecimento';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Fala-se muito nos dias de hoje em direitos do homem. Pois bem: foi no século XVIII — em 1789, precisamente — que uma Assembleia Constituinte produziu e proclamou em Paris a Declaração dos Direitos do Homem e do Cidadão. Essa Declaração se impôs como necessária para um grupo de revolucionários, por ter sido preparada por uma mudança no plano das ideias e das mentalidades: o lluminismo.

FORTES, L. R. S. O lluminismo e os reis filósofos. São Paulo: Brasiliense, 1981 (adaptado).', N'Correlacionando temporalidades históricas, o texto apresenta uma concepção de pensamento que tem como uma de suas bases a', N'E', 1013, N'FACIL', 2017, 49, 'OFICIAL', N'INEP - ENEM 2017, questão 49 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
