INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Conquistar o apoio popular na legitimação do novo governo.', @q), ('B', N'Ampliar o envolvimento das multidões nas decisões políticas.', @q), ('C', N'Aumentar a oferta de informações públicas para a sociedade civil.', @q), ('D', N'Estender a participação democrática dos meios de comunicação no Brasil.', @q), ('E', N'Alargar o entendimento da população sobre as intenções do novo governo.', @q);
