INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Assegura que a ação seja aceita por todos a partir da livre discussão participativa.', @q), ('B', N'Garante que os efeitos das ações não destruam a possibilidade da vida futura na terra.', @q), ('C', N'Opõe-se ao princípio de que toda ação do homem possa valer como norma universal.', @q), ('D', N'Materializa-se no entendimento de que os fins da ação humana podem justificar os meios.', @q), ('E', N'Permite que a ação individual produza a mais ampla felicidade para as pessoas envolvidas.', @q);
