INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A distrofia muscular Duchenne (DMD) é uma doença causada por uma mutação em um gene localizado no cromossomo X. Pesquisadores estudaram uma família na qual gêmeas monozigóticas eram portadoras de um alelo mutante recessivo para esse gene (heterozigóticas). O interessante é que uma das gêmeas apresentava o fenótipo relacionado ao alelo mutante, isto é, DMD, enquanto a sua irmã apresentava fenótipo normal.

RICHARDS, C. S. et al. The American Journal of Human Genetics, n. 4, 1990 (adaptado).', N'A diferença na manifestação da DMD entre as gêmeas pode ser explicada pela', N'D', 1017, N'FACIL', 2017, 117, 'OFICIAL', N'INEP - ENEM 2017, questão 117 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Dominância incompleta do alelo mutante em relação ao alelo normal.', @q), ('B', N'Falha na separação dos cromossomos X no momento da separação dos dois embriões.', @q), ('C', N'Recombinação cromossômica em uma divisão celular embrionária anterior à separação dos dois embriões.', @q), ('D', N'Inativação aleatória de um dos cromossomos X em fase posterior à divisão que resulta nos dois embriões.', @q), ('E', N'Origem paterna do cromossomo portador do alelo mutante em uma das gêmeas e origem materna na outra.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Alguns tipos de dessalinizadores usam o processo de osmose reversa para obtenção de água potável a partir da água salgada. Nesse método, utiliza-se um recipiente contendo dois compartimentos separados por uma membrana semipermeável: em um deles coloca-se água salgada e no outro recolhe-se a água potável. A aplicação de pressão mecânica no sistema faz a água fluir de um compartimento para o outro. O movimento das moléculas de água através da membrana é controlado pela pressão osmótica e pela pressão mecânica aplicada.', N'Para que ocorra esse processo é necessário que as resultantes das pressões osmótica e mecânica apresentem', N'E', 1064, N'MEDIO', 2017, 120, 'OFICIAL', N'INEP - ENEM 2017, questão 120 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
