INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Literatura' AND t.nome = N'Análise de poemas e narrativas';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'**A imagem da negra e do negro em produtos de**  
**beleza e a estética do racismo**

**Resumo:** Este artigo tem por finalidade discutir a representação da população negra, especialmente da mulher negra, em imagens de produtos de beleza presentes em comércios do nordeste goiano. Evidencia-se que a presença de estereótipos negativos nessas imagens dissemina um imaginário racista apresentado sob a forma de uma estética racista que camufla a exclusão e normaliza a inferiorização sofrida pelos(as) negros(as) na sociedade brasileira. A análise do material imagético aponta a desvalorização estética do negro,  
especialmente da mulher negra, e a idealização da beleza e do branqueamento a serem alcançados por meio do uso dos produtos apresentados. O discurso midiático-publicitário dos produtos de beleza rememora e legitima a prática de uma ética racista construída e atuante no cotidiano. Frente a essa discussão, sugere-se que o trabalho antirracismo, feito nos diversos espaços sociais, considere o uso de estratégias para uma “descolonização estética” que empodere os sujeitos negros por meio de sua valorização estética e protagonismo na construção de uma ética da diversidade.

Palavras-chave: Estética, racismo, mídia, educação, diversidade.

SANT’ANA, J. A imagem da negra e do negro em produtos de beleza e a estética do racismo. Dossiê: trabalho e educação básica. **Margens Interdisciplinar**.  
Versão digital. Abaetetuba, n.16,jun. 2017 (adaptado).', N'O cumprimento da função referencial da linguagem é uma marca característica do gênero resumo de artigo acadêmico. Na estrutura desse texto, essa função é estabelecida pela', N'A', 1037, N'FACIL', 2018, 24, 'OFICIAL', N'INEP - ENEM 2018, questão 24 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Língua Portuguesa'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Impessoalidade, na organização da objetividade das informações, como em “Este artigo tem por finalidade” e “Evidencia-se”.', @q), ('B', N'Seleção lexical, no desenvolvimento sequencial do texto, como em “imaginário racista” e “estética do negro”.', @q), ('C', N'Metaforização, relativa à construção dos sentidos figurados, como nas expressões “descolonização estética” e “discurso midiático-publicitário”.', @q), ('D', N'Nominalização, produzida por meio de processos derivacionais na formação de palavras, como “inferiorização” e “desvalorização”.', @q), ('E', N'Adjetivação, organizada para criar uma terminologia antirracista, como em “ética da diversidade” e “descolonização estética”.', @q);
