INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Engajamento de civis analfabetos após a emergência de guerras externas.', @q), ('B', N'Insatisfação de militares positivistas após a consolidação da política dos governadores.', @q), ('C', N'Rebaixamento de comandantes veteranos após a repressão a insurreições milenaristas.', @q), ('D', N'Sublevação das classes populares do campo após a instituição do alistamento obrigatório.', @q), ('E', N'Manutenção da mentalidade escravocrata da oficialidade após a queda do regime imperial.', @q);
