INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Descritivo e argumentativo, pois o enunciador detalha cada lugar por onde passa, argumentando contra a violência urbana.', @q), ('B', N'Dissertativo e argumentativo, pois o enunciador apresenta seu ponto de vista sobre as notícias relativas à cidade.', @q), ('C', N'Expositivo e injuntivo, pois o enunciador fala de seus estados físicos e psicológicos e interage com a mulher amada.', @q), ('D', N'Narrativo e descritivo, pois o enunciador conta sobre suas andanças pelas ruas da cidade ao mesmo tempo que a descreve.', @q), ('E', N'Narrativo e injuntivo, pois o enunciador ensina o interlocutor como andar pelas ruas da cidade contanto sobre sua própria experiência.', @q);
