INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Estagnação de direitos adquiridos e do anacronismo da legislação vigente.', @q), ('B', N'Manutenção do status quo gerencial e dos padrões de socialização familiar.', @q), ('C', N'Desestruturação da herança patriarcal e das mudanças do perfil ocupacional.', @q), ('D', N'Disputas na composição sindical e da presença na esfera político-partidária.', @q), ('E', N'Exigências de aperfeiçoamento profissional e de habilidades na competência diretiva.', @q);
