INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'Brasil Colônia e Império';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Será que as coisas pareceriam diferentes se, de fato, todas elas existissem apenas na sua mente — se tudo o que você julgasse ser o mundo externo real fosse apenas um sonho ou alucinação gigante, de que você jamais fosse despertar? Se assim fosse, então é claro que você nunca poderia despertar, como faz quando sonha, pois significaria que não há mundo “real” no qual despertar. Logo, não seria exatamente igual a um sonho ou alucinação normal.

NAGEL, T. **Uma breve introdução à filosofia**. São Paulo: Martins Fontes, 2011.', N'O texto confere visibilidade a uma doutrina filosófica contemporânea conhecida como:', N'E', 1017, N'FACIL', 2020, 55, 'OFICIAL', N'INEP - ENEM 2020, questão 55 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Personalismo, que vincula a realidade circundante aos domínios do pessoal.', @q), ('B', N'Falsificacionismo, que estabelece ciclos de problemas para refutar a conjectura.', @q), ('C', N'Falibilismo, que rejeita mecanismos mentais para sustentar uma crença inequívoca.', @q), ('D', N'Idealismo, que nega a existência de objetivos independentemente do trabalho cognoscente.', @q), ('E', N'Solipsismo, que reconhece limitações cognitivas para compreender uma experiência compartilhada.', @q);
