INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'Brasil Colônia e Império';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Desde o mundo antigo e sua filosofia, que o trabalho tem sido compreendido como expressão de vida e degradação, criação e infelicidade, atividade vital e escravidão, felicidade social e servidão. Trabalho e fadiga. Na Modernidade, sob o comando do mundo da mercadoria e do dinheiro, a prevalência do negócio (negar o ócio) veio sepultar o império do repouso, da folga e da preguiça, criando uma ética positiva de trabalho.

ANTUNES, R. O século XX e a era da degradação do trabalho. In: SILVA, J.P. (Org.). Por uma sociologia do século XX. São Paulo: Annablume, 2007 (adaptado).', N'O processo de ressignificação do trabalho nas sociedades modernas teve início a partir do surgimento de uma nova mentalidade, influenciada pela', N'B', 1019, N'FACIL', 2020, 63, 'OFICIAL', N'INEP - ENEM 2020, questão 63 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Reforma higienista, que combateu o caráter excessivo e insalubre do trabalho fabril.', @q), ('B', N'Reforma Protestante, que expressou a importância das atividades laborais no mundo secularizado.', @q), ('C', N'Força do sindicalismo, que emergiu no esteio do anarquismo reivindicando direitos trabalhistas.', @q), ('D', N'Participação das mulheres em movimentos sociais, defendendo o direito ao trabalho.', @q), ('E', N'Visão do catolicismo, que, desde a Idade Média, defendia a dignidade do trabalho e do lucro.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'Brasil Colônia e Império';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'É difícil imaginar que nos anos 1990, num país com setores da população na pobreza absoluta e sem uma rede de benefícios sociais em que se apoiar, um governo possa abandonar o papel de promotor de programas de geração de emprego, de assistência social, de desenvolvimento da infraestrutura e de promoção de regiões excluídas, na expectativa de que o mercado venha algum dia a dar uma resposta adequada a tudo isso.

SORJ, B. **A nova sociedade brasileira**. Rio de Janeiro: Jorge Zahar, 2000 (adaptado).', N'Nesse contexto, a criticada postura dos governos frente à situação social do país coincidiu com a priorização de que medidas?', N'E', 1017, N'FACIL', 2020, 64, 'OFICIAL', N'INEP - ENEM 2020, questão 64 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Expansão dos investimentos nas empresas públicas e nos bancos estatais.', @q), ('B', N'Democratização do crédito habitacional e da aquisição de moradias populares.', @q), ('C', N'Enxugamento da carga fiscal individual e da contribuição tributária empresarial.', @q), ('D', N'Reformulação do acesso ao ensino superior e do financiamento científico nacional.', @q), ('E', N'Reforma das políticas macroeconômicas e dos mecanismos de controle inflacionário.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia urbana e população';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Um dos resquícios franceses na dança são os comandos proferidos pelo marcador da quadrilha. Seu papel é anunciar os próximos passos da coreografia. O abrasileiramento de termos franceses deu origem, por exemplo, ao saruê (_soirée_ — reunião social noturna, ordem para todos se juntarem no centro do salão), anarriê (_en arrière_ — para trás) e anavã (_en avant_ — para frente).

Disponível em: www.ebc.com.br. Acesso em: 6 jul. 2015.', N'A característica apresentada dessa manifestação popular resulta do seguinte processo socio-histórico:', N'E', 1011, N'FACIL', 2020, 66, 'OFICIAL', N'INEP - ENEM 2020, questão 66 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
