INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Ao abrigo do teto, sua jornada de fé começava na sala de jantar. Na pequena célula cristã, dividia-se a refeição e durante elas os crentes conversavam, rezavam e liam cartas de correligionários residentes em locais diferentes do Império Romano (século II da Era Cristã). Esse ambiente garantia peculiar apoio emocional às experiências intensamente individuais que abrigava.

SENNET, R. **Carne e pedra**. Rio de Janeiro. Record, 2008.', N'Um motivo que explica a ambientação da prática descrita no texto encontra-se no(a)', N'D', 1015, N'FACIL', 2020, 83, 'OFICIAL', N'INEP - ENEM 2020, questão 83 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Regra judaica, que pregava a superioridade espiritual dos cultos das sinagogas.', @q), ('B', N'Moralismo da legislação, que dificultava as reuniões abertas da juventude livre.', @q), ('C', N'Adesão do patriarcado, que subvertia o conceito original dos valores estrangeiros.', @q), ('D', N'Decisão política, que censurava as manifestações públicas da doutrina dissidente.', @q), ('E', N'Violência senhorial, que impunha a desestruturação forçada das famílias escravas.', @q);
