INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia física e clima';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O movimento sedicioso ocorrido na capitania de Pernambuco, no ano 1817, foi analisado de formas diferentes por dois meios de comunicação daquela época. O Correio Braziliense apontou para o fato de ser “a comoção no Brasil motivada por um descontentamento geral, e não por maquinações de alguns indivíduos”. Já a Gazeta do Rio de Janeiro considerou o movimento como um “pontual desvio de norma, apenas uma ‘mancha’ nas ‘páginas da História Portuguesa’, tão distinta pelos testemunhos de amor e respeito que os vassalos desta nação consagram ao seu soberano”.

JANCSÓ, I; PIMENTA, J. P. Peças de um mosaico. In: MOTA, C. G. (Org.). **Viagem Incompleta**: a experiência brasileira (1500-2000). São Paulo: Senac, 2000 (adaptado).', N'Os fragmentos das matérias jornalísticas sobre o acontecimento, embora com percepções diversas, relacionam-se a um aspecto do processo de independência da colônia luso-americana expresso em dissensões entre', N'B', 1020, N'FACIL', 2020, 85, 'OFICIAL', N'INEP - ENEM 2020, questão 85 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'História'));
