INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Quadros dirigentes em torno da abolição da ordem escravocrata.', @q), ('B', N'Grupos regionais acerca da configuração político-territorial.', @q), ('C', N'Intelectuais laicos acerca da revogação do domínio eclesiástico.', @q), ('D', N'Homens livres em torno da extensão do direito de voto.', @q), ('E', N'Elites locais acerca da ordenação do monopólio fundiário.', @q);
