INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Nitrogênio, devido à nitrificação ambiental transformando amônia em nitrito.', @q), ('B', N'Nitrogênio, devido ao aumento dos compostos nitrogenados no ambiente terrestre.', @q), ('C', N'Carbono, devido ao aumento dos carbonatos dissolvidos no ambiente marinho.', @q), ('D', N'Carbono, devido à liberação das cadeias carbônicas aprisionadas abaixo dos sedimentos.', @q), ('E', N'Fósforo, devido à liberação dos fosfatos acumulados no ambiente marinho.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Química orgânica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Em uma usina geradora de energia elétrica, seja através de uma queda-d’água ou através de vapor sob pressão, as pás do gerador são postas a girar. O movimento relativo de um ímã em relação a um conjunto de bobinas produz um fluxo magnético variável através delas, gerando uma diferença de potencial em seus terminais. Durante o funcionamento de um dos geradores, o operador da usina percebeu que houve um aumento inesperado da diferença de potencial elétrico nos terminais das bobinas.', N'Nessa situação, o aumento do módulo da diferença de potencial obtida nos terminais das bobinas resulta do aumento do(a)', N'D', 1070, N'MEDIO', 2020, 98, 'OFICIAL', N'INEP - ENEM 2020, questão 98 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Intervalo de tempo em que as bobinas ficam imersas no campo magnético externo, por meio de uma diminuição de velocidade no eixo de rotação do gerador.', @q), ('B', N'Fluxo magnético através das bobinas, por meio de um aumento em sua área interna exposta ao campo magnético aplicado.', @q), ('C', N'Intensidade do campo magnético no qual as bobinas estão imersas, por meio de aplicação de campos magnéticos mais intensos.', @q), ('D', N'Rapidez com que o fluxo magnético varia através das bobinas, por meio de um aumento em sua velocidade angular.', @q), ('E', N'Resistência interna do condutor que constitui as bobinas, por meio de um aumento na espessura dos terminais.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Mecânica e movimento';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O dióxido de carbono passa para o estado sólido (gelo seco) a –78 °C e retorna ao estado gasoso à temperatura ambiente. O gás é facilmente solubilizado em água, capaz de absorver radiação infravermelha da superfície da terra e não conduz eletricidade. Ele é utilizado como maté – ria-prima para a fotossíntese até o limite de saturação. Após a fixação pelos organismos autotróficos, o gás retorna ao meio ambiente pela respiração aeróbica, fermentação, decomposição ou por resíduos industriais, queima de combustíveis fósseis e queimadas. Apesar da sua importância ecológica, seu excesso causa perturbações no equilíbrio ambiental.', N'Considerando as propriedades descritas, o aumento atmosférico da substância afetará os organismos aquáticos em razão da', N'A', 1066, N'MEDIO', 2020, 103, 'OFICIAL', N'INEP - ENEM 2020, questão 103 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Redução do potencial hidrogeniônico da água.', @q), ('B', N'Restrição da aerobiose pelo excesso de poluentes.', @q), ('C', N'Diminuição da emissão de oxigênio pelos autótrofos.', @q), ('D', N'Limitação de transferência de energia entre os seres vivos.', @q), ('E', N'Retração dos oceanos pelo congelamento do gás nos polos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Reações e equilíbrio químico';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Grupos de proteção ao meio ambiente conseguem resgatar muitas aves aquáticas vítimas de vazamentos de petróleo. Essas aves são lavadas com água e detergente neutro para a retirada completa do óleo de seu corpo e, posteriormente, são aquecidas, medicadas, desintoxicadas e alimentadas. Mesmo após esses cuidados, o retorno ao ambiente não pode ser imediato, pois elas precisam recuperar a capacidade de flutuação.', N'Para flutuar, essas aves precisam', N'E', 1060, N'MEDIO', 2020, 104, 'OFICIAL', N'INEP - ENEM 2020, questão 104 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
