INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Contestar o ensino de regras em detrimento do conteúdo das informações.', @q), ('B', N'Resgatar valores patrióticos relacionados às tradições da língua portuguesa.', @q), ('C', N'Adotar uma perspectiva complacente em relação aos desvios gramaticais.', @q), ('D', N'Invalidar os usos da língua pautados pelos preceitos da gramática normativa.', @q), ('E', N'Desconsiderar diferentes níveis de formalidade nas situações de comunicação.', @q);
