INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Alianças afetivas conectadas a ritual matrimonial. B Práticas místicas associadas a patrimônio cultural. © Manifestações teatrais atreladas a imaginário político. d Narrativas filmicas relacionadas às intempéries climáticas. © Argumentações literárias interligadas às catástrofes ambientais.', @q), ('B', N'Práticas místicas associadas a patrimônio cultural. Manifestações teatrais atreladas a imaginário político. d Narrativas filmicas relacionadas às intempéries climáticas. © Argumentações literárias interligadas às catástrofes ambientais.', @q), ('C', N'Manifestações teatrais atreladas a imaginário político.', @q), ('D', N'Narrativas filmicas relacionadas às intempéries climáticas.', @q), ('E', N'Argumentações literárias interligadas às catástrofes ambientais.', @q);
