INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia agrária e economia';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'As atividades mineradores têm criado conflitos com extrativistas, quilombolas, pequenos agricultores, ribeirinhos, pescadores artesanais e povos indígenas. Em geral, estes sujeitos têm encontrado grande dificuldade de reproduzi suas dinâmicas territoriais depois da instalação da atividade mineradora , nem sempre com reconhecimento do impacto ao seu território pelo Estado e pela empresa, ficando sem qualquer tipo de compensação econômica. Em outros casos, nem a compensação econômica tem sido capaz de evitar esgarçamento das relações sociais destes grupos que sofrem com a reconstrução abrupta das suas identidades e de suas dinâmicas territoriais.

PALHETA, J. M. et al. Conflitos pelo uso do território na Amazônica mineral. **Mercator**, n. 16. 2017.', N'O texto apresenta uma relação entre atividade econômica e organização social marcada pelo(a)', N'B', 1017, N'FACIL', 2021, 63, 'OFICIAL', N'INEP - ENEM 2021, questão 63 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
