INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Enfraquecer as formas de militância política.', @q), ('B', N'Abalar a identidade de povos tradicionais.', @q), ('C', N'Inserir as comunidades no mercado global.', @q), ('D', N'Distanciar os grupos de culturas locais.', @q), ('E', N'Angariar o apoio de segmentos étnicos externos.', @q);
