INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Literatura' AND t.nome = N'Análise de poemas e narrativas';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O Recife fervilhava no começo da década de 1990, e os artistas trabalhavam para resgatar o prestígio da cultura pernambucana. Era preciso se inspirar, literalmente, nas raízes sobre as quais a cidade se construiu. Foi aí que, em 1992, com a publicação de um manifesto escrito pelo músico e jornalista Fred Zero Quatro, da banda Mundo Livre S/A, nasceu o manguebeat. O nome vem de “mangue”, vegetação típica da região, e “beat”, para representar as batidas e as influências musicais que o movimento abraçaria a partir dali. Era a hora e a vez de os caranguejos – aos quais os músicos recifenses gostavam de se comparar – mostrarem as caras: o maracatu e suas alfaias se misturaram com as batidas do hip-hop, as guitarras do rock, elementos eletrônicos e o sotaque recifense de Chico Science. A busca pelo novo rendeu uma perspectiva diferente do Brasil ao olhar para o Recife. A cidade deixou de ser o lugar apenas do frevo e do carnaval, transformando-se na ebulição musical que continua a acontecer mesmo após os 25 anos do lançamento do primeiro disco da Nação Zumbi, Da lama ao caos.

FORCIONI, G. et al. O mangue está de volta. **Revista Esquinas**, n. 87, set 2019 (adaptado).', N'Chico Science foi fundamental para a renovação da música pernambucana, fato que se deu pela', N'E', 1028, N'FACIL', 2022, 45, 'OFICIAL', N'INEP - ENEM 2022, questão 45 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Artes e Educação Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Utilização de aparelhos musicais eletrônicos em lugar dos instrumentos tradicionais.', @q), ('B', N'Ocupação de espaços da natureza local para a produção de eventos musicais memoráveis.', @q), ('C', N'Substituição de antigas práticas musicais, como o frevo, por melodias e harmonias inovadoras.', @q), ('D', N'Recuperação de composições tradicionais folclóricas e sua apresentação em grandes festivais.', @q), ('E', N'Integração de referenciais culturais de diferentes origens, criando uma nova combinação estética.', @q);
