INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Delimitação de paisagens urbanas e abandono de componentes espiritualistas.', @q), ('B', N'Demarcação de patrimônios afetivos e apropriação de elementos judaizantes.', @q), ('C', N'Expansão de fronteiras regionais e subjetivação do cristianismo medieval.', @q), ('D', N'Circunscrição de bens simbólicos e admissão de cerimônias ecumênicas.', @q), ('E', N'Criação de lugares místicos e experiências do catolicismo popular.', @q);
