INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'As populações com idioma comum devem estar submetidas à mesma autoridade estatal.', @q), ('B', N'O imperialismo soviético havia se acomodado às pretensões das potências vizinhas.', @q), ('C', N'Os organismos transnacionais são incapazes de solucionar disputas territoriais.', @q), ('D', N'A integração regional supõe a livre circulação de pessoas e mercadorias.', @q), ('E', N'Expulsão das forças navais ocidentais garantiria a soberania nacional.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Filosofia' AND t.nome = N'Ética e política';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O princípio básico do Estado de direito é o da eliminação do arbítrio no exercício dos poderes  públicos, com a consequente garantia de direitos dos indivíduos perante esses poderes. Estado de direito significa que nenhum indivíduo, presidente ou cidadão comum está acima da lei. Os governos democráticos exercem a autoridade por meio da lei e estão eles próprios sujeitos as constrangimentos impostos pela lei.

**CANOTILHO, J. J. G. Estado de direito, Lisboa: Gradiva, 1999 (adaptado).**', N'Nas sociedades contemporâneas, consiste em violação do princípio básico enunciado no texto:', N'A', 1014, N'FACIL', 2022, 71, 'OFICIAL', N'INEP - ENEM 2022, questão 71 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
SET @q = SCOPE_IDENTITY();
