INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'De acordo com a Organização Mundial da Saúde, a filariose e a leishmaniose são consideradas doenças  
tropicais infecciosas e constituem uma preocupação para a saúde pública por ser alto o índice de mortalidade a elas associado.', N'Uma medida profilática comum a essas duas doenças é o(a)', N'D', 1007, N'FACIL', 2022, 92, 'OFICIAL', N'INEP - ENEM 2022, questão 92 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
