INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A Agência Nacional de Vigilância Sanitária (Anvisa) aprovou um produto de terapia gênica no país, indicado para o tratamento da distrofia hereditária da retina. O procedimento é recomendado para crianças acima de 12 meses e adultos com perda de visão causada pela mutação do gene humano RPE65. O produto, elaborado por engenharia genética, é composto por um vírus, no qual foi inserida uma cópia do gene normal humano RPE65 para corrigir o funcionamento das células da retina.

ANVISA. Disponível em: www.gov.br/anvisa. Acesso em: 4 dez. 2021 (adaptado)', N'O sucesso dessa terapia advém do fato de que o produto favorecerá a', N'E', 1015, N'FACIL', 2022, 98, 'OFICIAL', N'INEP - ENEM 2022, questão 98 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Correção do código genético para a tradução da proteína.', @q), ('B', N'Alteração do RNA ribossômico ligado à síntese da proteína.', @q), ('C', N'Produção de mutações benéficas para a correção do problema.', @q), ('D', N'Liberação imediata da proteína normal na região ocular humana.', @q), ('E', N'Expressão do gene responsável pela produção da enzima normal.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A extinção de espécies é uma ameaça real que afeta diversas regiões do país. A introdução de espécies exóticas pode ser considerada um fator maximizador desse processo. A jaqueira (_Artocarpus heterophyllus_), por exemplo, é uma árvore originária da Índia e de regiões do Sudeste Asiático que foi introduzida ainda na era colonial e se aclimatou muito bem em praticamente todo o território nacional.', N'Casos como o dessa árvore podem provocar a redução da biodiversidade, pois elas', N'A', 1016, N'FACIL', 2022, 99, 'OFICIAL', N'INEP - ENEM 2022, questão 99 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Ocupam áreas de vegetação nativa e substituem parcialmente a flora original.', @q), ('B', N'Estimulam a competição por seus frutos entre animais típicos da região e eliminam as espécies perdedoras.', @q), ('C', N'Alteram os nichos e aumentam o número de possibilidades de relações entre os seres vivos daquele ambiente.', @q), ('D', N'Apresentam alta taxa de reprodução e se mantêm com um número de indivíduos superior à capacidade suporte do ambiente.', @q), ('E', N'Diminuem a relação de competição entre os polinizadores e facilitam a ação de dispersores de sementes de espécies nativas.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Ecologia e meio ambiente';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Entre as diversas técnicas para diagnóstico da covid-19, destaca-se o teste genético. Considerando as diferentes variantes e cargas virais, um exemplo é a PCR, reação efetuada por uma enzima do tipo polimerase. Essa técnica permite identificar, com confiabilidade, o material genético do SARS-CoV-2, um vírus de RNA.  
Para comprovação da infecção por esse coronavírus, são coletadas amostras de secreções do indivíduo. Uma etapa que antecede a reação de PCR precisa ser realizada para permitir a amplificação do material genético do vírus.', N'Essa etapa deve ser realizada para', N'E', 1014, N'FACIL', 2022, 102, 'OFICIAL', N'INEP - ENEM 2022, questão 102 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Concentrar o RNA viral para otimizar a técnica.', @q), ('B', N'Identificar nas amostras anticorpos anti-SARS-CoV-2.', @q), ('C', N'Proliferar o vírus em culturas, aumentando a carga viral.', @q), ('D', N'Purificar ácidos nucleicos virais, facilitando a ação da enzima.', @q), ('E', N'Obter moléculas de cDNAviral por meio da transcrição reversa.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Diversas substâncias são empregadas com a intenção de incrementar o desempenho esportivo de atletas de alto nível. O chamado _doping_ sanguíneo, por exemplo, pela utilização da eritropoietina, é proibido pelas principais federações de esportes no mundo. A eritropoietina é um hormônio produzido pelos rins e fígado e sua principal ação é regular o processo de eritropoiese. Seu uso administrado intravenosamente em quantidades superiores àquelas presentes naturalmente no organismo permite que o indivíduo aumente a sua capacidade de realização de exercícios físicos.', N'Esse tipo de doping está diretamente relacionado ao aumento da', N'E', 1063, N'MEDIO', 2022, 104, 'OFICIAL', N'INEP - ENEM 2022, questão 104 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Frequência cardíaca.', @q), ('B', N'Capacidade pulmonar.', @q), ('C', N'Massa muscular do indivíduo.', @q), ('D', N'Atividade anaeróbica da musculatura.', @q), ('E', N'Taxa de transporte de oxigênio pelo sangue.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Ondulatória e óptica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Em um autódromo, os carros podem derrapar em uma curva e bater na parede de proteção. Para diminuir o impacto de uma batida, pode-se colocar na parede uma barreira de pneus, isso faz com que a colisão seja mais demorada e o carro retorne com velocidade reduzida. Outra opção é colocar uma barreira de blocos de um material que se deforma, tornando-a tão demorada quanto a colisão com os pneus, mas que não permite a volta do carro após a colisão.', N'Comparando as duas situações, como ficam a força média exercida sobre o carro e a energia mecânica dissipada?', N'A', 1068, N'MEDIO', 2022, 105, 'OFICIAL', N'INEP - ENEM 2022, questão 105 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'A força é maior na colisão com a barreira de pneus, e a energia dissipada é maior na colisão com a barreira de blocos.', @q), ('B', N'A força é maior na colisão com a barreira de blocos, e a energia dissipada é maior na colisão com a barreira de pneus.', @q), ('C', N'A força é maior na colisão com a barreira de blocos, e a energia dissipada é a mesma nas duas situações.', @q), ('D', N'A força é maior na colisão com a barreira de pneus, e a energia dissipada é maior na colisão com a barreira de pneus.', @q), ('E', N'A força é maior na colisão com a barreira de blocos, e a energia dissipada é maior na colisão com a barreira de blocos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Mecânica e movimento';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Desde a proposição da teoria de seleção natural  
por Darwin, os seres vivos nunca mais foram olhados  
da mesma forma. No que diz respeito à reprodução de  
anfíbios anuros, os cientistas já descreveram diferentes  
padrões reprodutivos, como os exemplificados a seguir:  
Espécie 1 – As fêmeas produzem cerca de  
5 000 gametas, que são fecundados na água, em  
lagoas temporárias de estação chuvosa. Todo o  
desenvolvimento embrionário, do ovo à metamorfose,  
ocorre, nesse ambiente, independente dos pais.  
Espécie 2 – As fêmeas produzem aproximadamente  
200 gametas, que são depositados em poças próximas a  
corpos-d’água. Os embriões são vigiados pelos machos  
durante boa parte do seu desenvolvimento.  
Espécie 3 – As fêmeas produzem por volta de  
20 gametas, que são fecundados sobre a superfície das  
folhas de plantas cujos galhos estão dispostos acima da  
superfície de corpos-d’água e aí se desenvolvem até  
a eclosão.  
Espécie 4 – As fêmeas produzem poucos gametas  
que, quando fecundados, são “abocanhados” pelos  
machos. Os embriões se desenvolvem no interior do  
saco vocal do macho até a metamorfose, quando saem  
através da boca do pai.', N'Os padrões descritos evidenciam que', N'D', 1025, N'FACIL', 2022, 110, 'OFICIAL', N'INEP - ENEM 2022, questão 110 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'As fêmeas influenciam o comportamento dos machos.', @q), ('B', N'O cuidado parental é necessário para o desenvolvimento', @q), ('C', N'O grau de evolução determina o comportamento reprodutivo.', @q), ('D', N'O sucesso reprodutivo pode ser garantido por estratégias diferentes.', @q), ('E', N'O ambiente induz modificação na produção do número de gametas femininos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Um pai faz um balanço utilizando dois segmentos paralelos e iguais da mesma corda para fixar uma tábua a uma barra horizontal. Por segurança, opta por um tipo de corda cuja tensão de ruptura seja 25% superior à tensão máxima calculada nas seguintes condições:

• O ângulo máximo atingido pelo balanço em relação  
à vertical é igual a 90°;

• Os filhos utilizarão o balanço até que tenham uma  
massa de 24 kg.

Além disso, ele aproxima o movimento do balanço para o movimento circular uniforme, considera que a aceleração da gravidade é igual a 10  m/s² se despreza forças dissipativas.', N'Qual é a tensão de ruptura da corda escolhida?', N'D', 1061, N'MEDIO', 2022, 112, 'OFICIAL', N'INEP - ENEM 2022, questão 112 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
