INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Mecânica e movimento';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'As células da epiderme da folha da _Tradescantia pallida purpurea_, uma herbácea popularmente conhecida como trapoeraba-roxa, contém um vacúolo onde se encontra um pigmento que dá a coloração arroxeada a esse tecido. Em um experimento, um corte da epiderme de uma folha da trapoeraba-roxa foi imerso em ambiente hipotônico e, logo em seguida, foi colocado em uma lâmina e observado em microscópio óptico.', N'Durante a observação desse corte, foi possível identificar o(a)', N'C', 1012, N'FACIL', 2022, 114, 'OFICIAL', N'INEP - ENEM 2022, questão 114 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Acúmulo do solvente com fragmentação da organela.', @q), ('B', N'Rompimento da membrana celular com liberação do citosol.', @q), ('C', N'Aumento do vacúolo com diluição do pigmento no seu interior.', @q), ('D', N'Quebra da parede celular com extravasamento do pigmento.', @q), ('E', N'Murchamento da célula com expulsão do pigmento do vacúolo.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Citologia e bioquímica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Uma lanterna funciona com três pilhas de resistência interna igual a 0,5 Ω cada, ligadas em série. Quando posicionadas corretamente, devem acender a lâmpada incandescente de especificações 4,5 W e 4,5 V. Cada pilha na posição correta gera uma f.e.m. (força eletromotriz) de 1,5 V. Uma pessoa, ao trocar as pilhas da lanterna, comete o equívoco de inverter a posição de uma das pilhas. Considere que as pilhas mantêm contato independentemente da posição.', N'Com esse equívoco, qual é a intensidade de corrente que passa pela lâmpada ao se ligar a lanterna?', N'A', 1059, N'MEDIO', 2022, 119, 'OFICIAL', N'INEP - ENEM 2022, questão 119 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
