INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O uso das redes sociais como forma de ampliar universos foi uma descoberta recente para o artista Wolney Fernandes, que começou a criar quando o ambiente em Goiás era mais árido em relação às artes visuais. “Hoje, ser diferente é uma potência e quem sabe o que quer com a própria arte encontra espaço”, diz. As colagens artísticas do goiano aparecem em capas de obras literárias pelo Brasil e exterior.

Disponível em: https://opopular.com.br. Acesso em: 15 nov. 2021 (adaptado).', N'O artista goiano Wolney Fernandes busca expor seu trabalho por meio de plataformas virtuais com o objetivo de', N'C', 1018, N'FACIL', 2023, 37, 'OFICIAL', N'INEP - ENEM 2023, questão 37 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Língua Portuguesa'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Dar suporte à técnica de colagem em Artes Visuais, contornando dificuldades práticas.', @q), ('B', N'Aproximar-se da estética visual própria da editoração de obras artísticas, como capas de livros.', @q), ('C', N'Oferecer uma vitrine internacional para sua produção artística, a fim de dar mais visibilidade a suas obras.', @q), ('D', N'Enfatizar o caráter original e inovador de suas criações artísticas, diferenciando-se das artes tradicionais.', @q), ('E', N'Trazer um sentido tecnológico às suas colagens, uma vez que as imagens artísticas são recorrentes nas redes sociais.', @q);
