INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A leishmaniose visceral é uma zoonose causada por um protozoário do gênero Leishmania que é encontrado em diversos tecidos. Ela é transmitida ao homem de forma indireta, por vetores do ambiente doméstico. O cão é considerado um importante hospedeiro desse protozoário, podendo ou não apresentar os sintomas da doença, como perda de peso, anemia, ferimentos na pele, diarreia, conjuntivite e insuficiência renal. Em uma região que sofre com alta incidência dessa doença, uma campanha do centro de zoonoses buscou verificar a presença desse protozoário nos cães para tentar controlar a doença.', NULL, N'D', 1010, N'FACIL', 2023, 99, 'OFICIAL', N'INEP - ENEM 2023, questão 99 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
