INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Ecologia e meio ambiente';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A tecnologia de vacinas de RNA mensageiro (RNAm) é investigada há anos. Avanços científicos em genética molecular permitiram desenvolver uma vacina para controle da pandemia da covid-19 causada pelo vírus de RNA SARS-CoV-2. A vacina de RNAm tem sequências de genes do vírus. Entretanto, por ser muito instável, o RNAm deve ser recoberto por uma capa de lipídios que evita sua degradação e favorece sua ação. Dessa forma, o RNAm desempenhará sua função especifica atuando no mesmo compartimento celular de sempre.

Disponível em: https://sbim.org.br. Acesso em: 29 nov. 2021 (adaptado).', N'A imunização produzida por esse tipo de vacina é alcançada por meio da', N'C', 1016, N'FACIL', 2023, 106, 'OFICIAL', N'INEP - ENEM 2023, questão 106 (caderno azul / 1ª aplicação)', N'https://www.gov.br/inep/pt-br/areas-de-atuacao/avaliacao-e-exames-educacionais/enem/provas-e-gabaritos', (SELECT id FROM Vestibular WHERE sigla = 'ENEM'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Estimulação de leucócitos induzida pela capa lipídica contendo RNAm.', @q), ('B', N'Atuação do RNAm como sequestrador do vírus para o meio extracelular.', @q), ('C', N'Tradução do RNAm em proteína viral, desencadeando a resposta antigênica.', @q), ('D', N'Competição entre o RNAm vacinal e o RNA viral pelos sítios dos ribossomos.', @q), ('E', N'Incorporação do RNAm viral ao genoma do hospedeiro. gerando novo fenótipo.', @q);
