INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Baterias íon-lítio (íon-Li) armazenam energia por meio de um processo de intercalação iônica, no qual íons Li+ penetram e se acomodam entre camadas de grafite no ânodo da bateria. A quantidade de energia armazenada é diretamente proporcional ao número de íons Li+ intercalados no ânodo, que, entre outros aspectos, é limitado pelo espaço disponível para a sua alocação. Uma recente inovação tecnológica em baterias é a substituição de Li por Na, formando baterias íonsódio (íon-Na). O mecanismo de funcionamento se baseia no processo de intercalação, com a vantagem de que o Na é mais abundante do que o Li no planeta.
Considerando que a única diferença entre baterias de mesma massa e volume seja o íon utilizado (Na+ ou Li+) e que a densidade de energia é a quantidade de energia armazenada na bateria por unidade de massa e volume, é correto afirmar que a densidade de energia de uma bateria íon-Na é', NULL, N'B', 1144, N'DIFICIL', 2025, 21, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 21 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'maior do que de uma bateria íon-Li, pois o Na+ tem maior massa e menor raio iônico do que o Li+.', @q), ('B', N'menor do que de uma bateria íon-Li, pois o Na+ tem maior massa e maior raio iônico do que o Li+.', @q), ('C', N'maior do que de uma bateria íon-Li, pois o Na+ tem menor massa e maior raio iônico do que o Li+.', @q), ('D', N'menor do que de uma bateria íon-Li, pois o Na+ tem menor massa e menor raio iônico do que o Li+.', @q), ('E', N'igual à de uma bateria íon-Li, pois ambos os íons são monovalentes. Note e adote: Distribuição eletrônica: Li = 1s2, 2s1; Na = 1s2, 2s2, 2p6, 3s1. Massa atômica (u): Li = 7; Na = 23.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Eletricidade e magnetismo';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Alguns corais contêm, em sua estrutura, algas fornecedoras de carboidratos que auxiliam no crescimento e na construção do esqueleto do coral. Os corais, por sua vez, fornecem um ambiente de proteção e importantes nutrientes às algas. As mudanças climáticas globais têm provocado a morte dessas algas e, em muitos casos, a morte dos corais.
Assinale a alternativa que representa a relação ecológica entre os corais e as algas, assim como o impacto imediato causado pela morte dos corais.

Relação ecológica', NULL, N'B', 1079, N'MEDIO', 2025, 31, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 31 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Predação', @q), ('B', N'Mutualismo', @q), ('C', N'Colônia', @q), ('D', N'Competição', @q), ('E', N'Comensalismo', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'Brasil Colônia e Império';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“São os ratos!... Vai escutar com atenção, a respiração meio parada. Hão de ser muitos: há várias fontes daquele guinchinho, e de quando em quando, no forro, em vários pontos, o rufar...
A casa está cheia de ratos...”
Dyonélio Machado. Os ratos.
A obra Os ratos (1935), de Dyonélio Machado, narra o dia em que Naziazeno saiu pela cidade de Porto Alegre no intuito de conseguir dinheiro para pagar a conta do leiteiro. Os animais que dão título à narrativa apenas aparecem em seus últimos capítulos e ocupam o tempo reservado para o descanso do protagonista. É possível, então, afirmar:', NULL, N'E', 1090, N'MEDIO', 2025, 34, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 34 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Naziazeno, inconformado com sua condição de devedor, perambula pela cidade, encontrando refúgio junto aos ratos que o acolhem.', @q), ('B', N'Os ratos são os credores de Naziazeno zoomorfizados, que se encontram à espreita para a cobrança de outras dívidas.', @q), ('C', N'Os “guinchinhos”, que ressoam nos ouvidos de Naziazeno, são o eco de seu dia de perambulação, como se lembrassem os obstáculos que venceu.', @q), ('D', N'Os ruídos dos roedores mostram que Naziazeno, ao pagar a sua dívida, esquece os obstáculos que venceu.', @q), ('E', N'O contraste entre o repouso de Naziazeno e o aparecimento dos roedores denuncia a permanência da sua situação de penúria social e financeira.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia física e clima';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“Ele vê o gesto do advogado Dr. Otávio Conti, no café, metendo a mão no bolso, tirando uma cédula de cem milréis e entregando-a ao Duque: ‘— Vá levantar esta letra. Você me devolve depois.’ Não é bem caridade... Ele não sabe explicar... Há nisso um certo tom de versatilidade... de facilidade... de um tal ou qual afrouxamento do caráter... Ele vê o Andrade tirando, com o gesto do Dr. Otávio Conti, a ‘mesma’ cédula do bolso e entregando-lha... A casa aristocrática acha-se perto. A numeração já está em quase trezentos. Uma pequena aragem que sopra levemente nesta parte alta da rua passa-lhe pelas mãos e esfria-as... O seu corpo suado fica como que um bloco gelado e dá-lhe a sensação de que se encolhe, se retrai dentro da sua roupa quente e assoleada, que dela se despega como duma carapaça. Ao mesmo tempo o coração, que batia lá no fundo do peito, veio palpitar bem à superfície, quase à flor da pele, meio engasgando-o.”
Dyonélio Machado. Os ratos.
Dentre as frases em destaque, a que caracteriza os efeitos fisiológicos em Naziazeno da reação de luta ou fuga pela ativação do sistema nervoso simpático é:', NULL, N'E', 1099, N'MEDIO', 2025, 35, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 35 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Artes e Educação Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Ele vê o gesto do advogado Dr. Otávio Conti, no café, metendo a mão no bolso, tirando uma cédula de cem milréis e entregando-a ao Duque.', @q), ('B', N'Ele não sabe explicar... Há nisso um certo tom de versatilidade... de facilidade... de um tal ou qual afrouxamento do caráter...', @q), ('C', N'Ele vê o Andrade tirando, com o gesto do Dr. Otávio Conti, a “mesma” cédula do bolso e entregando-lha... Concurso Vestibular FUVEST 2025 – Prova V1', @q), ('D', N'Uma pequena aragem que sopra levemente nesta parte alta da rua passa-lhe pelas mãos e esfria-as.', @q), ('E', N'Ao mesmo tempo o coração, que batia lá no fundo do peito, veio palpitar bem à superfície, quase à flor da pele, meio engasgando-o.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Artes e Educação Física' AND t.nome = N'Artes visuais, música e teatro';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A expressão bem-vinda usada no título e repetida no último verso faz alusão', NULL, N'C', 1128, N'DIFICIL', 2025, 37, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 37 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'ao aprisionamento da mulher que não consegue se libertar do poderio masculino.', @q), ('B', N'à guerra interior e à falta de forças da mulher oprimida, que aceita sua condição.', @q), ('C', N'ao renascimento da mulher que alcança, após a opressão, coragem para encontrar-se a si mesma.', @q), ('D', N'ao rebaixamento da mulher que se cala e se desculpa, perdendo aos poucos sua autoestima.', @q), ('E', N'à força da mulher que, mesmo hostilizada, tem poder para fazer entrar em sua casa quem a encurralava.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Hidrostática';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Atingir a igualdade de gênero é uma das metas do Objetivo de Desenvolvimento Sustentável (ODS) de número 5 da Agenda 2030, adotada pela ONU em 2015.
No cenário esportivo, é possível identificar alguns avanços em relação ao alcance dessa meta, conforme reconheceu a jogadora brasileira de futebol Marta:
“Quando as atletas do sexo feminino têm a chance de se destacar, os resultados são enormes. E para isso, a Copa do Mundo Feminina de 2019 foi realmente uma virada no jogo. A audiência global do torneio ultrapassou 1 bilhão de pessoas.”
Disponível em https://brasil.un.org/.
A Olimpíada de Paris 2024, por sua vez, estabeleceu, pela primeira vez na história, a paridade de gênero em todos os esportes olímpicos, com 5.250 vagas destinadas a cada sexo. Apesar das conquistas, o caminho rumo à igualdade de gênero continua.
Com base no exposto, é correto afirmar:', NULL, N'C', 1161, N'DIFICIL', 2025, 40, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 40 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'As práticas esportivas devem ser consideradas como práticas sociais, pois claramente refletem em sua realidade as potencialidades e os retrocessos da sociedade. Sendo assim, as mulheres já atingiram o mesmo nível de destaque que os homens na sociedade contemporânea, haja vista a ascensão e visibilidade feminina no cenário esportivo.', @q), ('B', N'Os grandes eventos esportivos conferem às mulheres uma visibilidade muitas vezes camuflada na sociedade. A visibilidade gerada para as atletas em cenário esportivo, a partir dos grandes eventos, demonstra o quanto elas já atingiram em totalidade seu status social e caminham no sentido de alcançar a agenda dos ODS.', @q), ('C', N'As mulheres atletas têm, vagarosamente, alcançado mais possibilidades de inclusão e participação junto ao mundo esportivo, porém a igualdade de gênero ainda se mostra uma meta distante de ser alcançada quando se observa a baixa proporção de mulheres ocupando cargos de gestão e liderança no cenário esportivo.', @q), ('D', N'O mundo esportivo não tem implicação direta junto ao alcance das metas dos ODS, uma vez que possui organização e regramento específicos, além de uma constituição social própria. Dessa maneira, a instituição esportiva não deve ser padrão de referência para revelar avanços ou retrocessos da sociedade como um todo.', @q), ('E', N'O esporte tem sido importante fenômeno de promoção das mulheres, mas sua influência é limitada à prática profissional de modalidades esportivas mais populares, sem potencial de contribuir para a igualdade de oportunidades para as mulheres em todos os níveis de tomada de decisão na vida política, econômica e pública.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Matemática' AND t.nome = N'Aritmética e álgebra';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Carlos Drummond de Andrade foi o criador de uma obra lírica que, ao mesmo tempo, se aproxima e se afasta do Modernismo de 1922, propondo, a partir de traços desse movimento, uma poética original. Com base no exposto, em Alguma poesia (1930),', NULL, N'C', 1089, N'MEDIO', 2025, 43, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 43 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Literatura'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'os aspectos prosaicos da linguagem modernista ganham expressão lírica a partir de um sujeito poético que repropõe, em versos livres, a nostalgia romântica da infância idealizada.', @q), ('B', N'o sujeito poético incorpora, sob a perspectiva de uma lírica de raiz subjetiva, vários procedimentos estilísticos das vanguardas modernistas, em especial a escrita automática e o surrealismo.', @q), ('C', N'a tópica literária do desconcerto do mundo ganha uma reconfiguração moderna, a partir de um sujeito poético que, mais do que revelar um mundo às avessas, focaliza o seu desajuste frente à realidade.', @q), ('D', N'o nacionalismo literário, tão típico da revisão empreendida pela primeira geração modernista sobre a realidade brasileira, apresenta-se como eixo temático de cunho ufanista.', @q), ('E', N'a paisagem mineira, no espaço literário, é configurada pelo sujeito poético como ambiente bucólico e refúgio privilegiado para os seus desajustes frente ao “vasto mundo”.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Literatura' AND t.nome = N'Escolas literárias';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A maior parte da alimentação humana é constituída por grãos e cereais, que, em sua maioria, correspondem às sementes, em termos botânicos. Esse consumo é adequado, uma vez que as sementes', NULL, N'D', 1083, N'MEDIO', 2025, 46, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 46 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'constituem o único órgão de reserva de amido das plantas, substância altamente energética para os seres vivos em geral.', @q), ('B', N'armazenam todas as vitaminas e nutrientes necessários para a planta e, portanto, também ao ser humano.', @q), ('C', N'possuem DNA da planta-mãe e do embrião, que constituem nutrientes sem os quais a espécie humana não sobrevive.', @q), ('D', N'contêm substâncias de reserva provedoras de energia para o desenvolvimento do embrião vegetal, que também servem de fonte energética aos seres humanos.', @q), ('E', N'possuem enzimas digestivas de amido e de proteínas, que disponibilizam energia ao embrião vegetal e também são usadas para promover a digestão em seres humanos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Botânica e zoologia';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Neste bioma, a vegetação nativa apresenta-se intercalada por extensas monoculturas de soja e de arroz. Em alguns lugares, a vegetação campestre original tem sido substituída por vegetação florestal, formada por árvores de eucaliptos. Em vários locais, observa-se a expansão de grandes areais, em que os solos arenosos ficam expostos e suscetíveis a uma intensa erosão. Este é o bioma brasileiro menos protegido por Unidades de Conservação, embora esteja entre aqueles que mais perderam vegetação nativa nas últimas três décadas.
A descrição da paisagem impactada por ações humanas refere-se ao bioma', NULL, N'D', 1080, N'MEDIO', 2025, 50, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 50 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Caatinga.', @q), ('B', N'Cerrado.', @q), ('C', N'Mata Atlântica.', @q), ('D', N'Pampas.', @q), ('E', N'Pantanal.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia física e clima';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A Estação Meteorológica Mirante de Santana é a principal referência do Instituto Nacional de Meteorologia (INMET) no município de São Paulo - SP. O climograma a seguir apresenta dados referentes ao mês de fevereiro de 2023. Neste mesmo mês, o Centro de Gerenciamento de Emergências Climáticas detectou 11 pontos de alagamentos no dia 19 e 14 pontos no dia 21.

Revista Pesquisa FAPESP – Setembro/2023 (Adaptado).
A explicação para as características desse perfil de temperatura do ar deve-se', NULL, N'A', 1139, N'DIFICIL', 2025, 53, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 53 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'à maior ocorrência de áreas verdes nas periferias, que absorvem mais radiação solar e aquecem o ambiente, ultrapassando os 32 °C.', @q), ('B', N'à maior absorção de radiação solar nas áreas centrais das cidades, compostas em sua maioria por asfalto, vidro e concreto.', @q), ('C', N'ao efeito de sombreamento dos edifícios nas áreas centrais, com maior disponibilidade de radiação solar e temperaturas inferiores a 30 °C.', @q), ('D', N'à presença de áreas comerciais e residenciais ao longo de todo perfil, que elevam a temperatura acima dos 32 °C e reduzem a umidade.', @q), ('E', N'à maior reflexão da radiação solar nas áreas centrais pelo asfalto, por apresentarem albedo menor que as superfícies vegetadas.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Ondulatória e óptica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“A distribuição dos mosquitos, a frequência de suas picadas e o tempo de eclosão de seus ovos são afetados pela temperatura, pluviosidade e velocidade do vento, além de outros fatores, como deslocamento e densidade populacionais. Por exemplo, com uma temperatura de 27 °C, o período de incubação dos ovos é de dez dias; no entanto, a 37 °C, esse período passa a ser de sete dias. Além disso, a intermitência das chuvas no final da estação do verão e os ventos calmos acentuam a proliferação e a atuação do vetor.”
MENDONÇA, Francisco de Assis. Aquecimento Global e Saúde: uma perspectiva geográfica – notas introdutórias. Terra Livre, 2003 (Adaptado).
Com base no texto, assinale a alternativa correta.', NULL, N'A', 1096, N'MEDIO', 2025, 54, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 54 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'A elevação da temperatura e o aumento da pluviosidade, somados ao desmatamento, à urbanização e à circulação de pessoas em várias áreas, potencializam a expansão da dengue.', @q), ('B', N'A dengue é um problema nacional e está relacionada ao fato de o Brasil ser um país tropical com áreas de florestas, aspectos que, combinados à dispersão da população, contribuem para minimizar a epidemia.', @q), ('C', N'A proliferação do mosquito Aedes aegypti ocorre em áreas pouco povoadas nos centros urbanos, associada às baixas temperaturas que intensificam a transmissão da doença.', @q), ('D', N'No território brasileiro, as áreas com baixas temperaturas reduzem o tempo necessário para eclosão dos ovos, aumentando a proliferação do mosquito Aedes aegypti e a frequência de picadas.', @q), ('E', N'A dengue é um problema de saúde pública em escala mundial e sua disseminação está associada à diminuição de temperatura, aumento da velocidade do vento e redução da precipitação.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia urbana e população';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Dentre os animais invertebrados, alguns grupos apresentam o sistema circulatório fechado, enquanto outros apresentam o sistema circulatório aberto, o que leva a diferenças em processos fisiológicos.
Nos invertebrados, o sistema circulatório', NULL, N'C', 1132, N'DIFICIL', 2025, 55, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 55 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'fechado apresenta uma menor pressão do sangue / hemolinfa em relação ao sistema circulatório aberto.', @q), ('B', N'aberto apresenta o coração dividido em quatro cavidades: dois átrios e dois ventrículos.', @q), ('C', N'fechado permite maior eficiência no transporte de oxigênio em relação ao sistema circulatório aberto.', @q), ('D', N'aberto facilita a distribuição dos nutrientes aos tecidos em relação ao sistema circulatório fechado.', @q), ('E', N'fechado mistura mais facilmente os gases respiratórios: oxigênio e dióxido de carbono.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Química orgânica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O processo de mumificação usado pelos egípcios começava com a retirada dos órgãos e desidratação do corpo utilizando uma mistura natural, obtida em leito de lagos, de sais solúveis de sódio, como carbonato, hidrogenocarbonato, cloreto e sulfato. Após a desidratação, o corpo era preenchido com uma

Concurso Vestibular FUVEST 2025 – Prova V1
mistura de serragem e ervas aromáticas como canela, cássia, mirra e até mesmo cebola, que, por conterem álcoois e aldeídos com propriedades antimicrobianas, dificultavam a decomposição do corpo. Por fim, o corpo era envolvido em tecido embebido em resinas insolúveis em água, como betume ou óleo de cedro, que, após seco, formava uma camada impermeabilizante. A partir dessas informações, assinale a alternativa correta.', NULL, N'E', 1140, N'DIFICIL', 2025, 56, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 56 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Os sais de sódio mencionados, por serem hidrofílicos, repelem a água.', @q), ('B', N'Propanona e hexano são exemplos de álcoois e aldeídos antimicrobianos.', @q), ('C', N'Assim como o betume e óleo de cedro, qualquer outro composto orgânico serviria como impermeabilizante.', @q), ('D', N'Todo sal iônico poderia ser utilizado em substituição aos sais de sódio mencionados.', @q), ('E', N'A impermeabilidade conferida pelas resinas se deve às suas características apolares ou muito pouco polares.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Química orgânica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A toxicidade do Pb e o risco de sua ingestão ganharam notoriedade na mídia devido à presença desse elemento em copos térmicos amplamente comercializados. A exposição ao Pb, no entanto, pode ocorrer também por fontes naturais, como a ingestão de água em contato prolongado com minérios como a anglesita, rico em PbSO4 (Kps = 1,0 × 10ꟷ8). Sabendo que a legislação estabelece a concentração máxima de Pb de 0,01 mg/L para água potável, assinale a alternativa correta em relação à ingestão de água que tenha contato prolongado com a anglesita.', NULL, N'A', 1137, N'DIFICIL', 2025, 58, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 58 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Não é segura, pois a concentração de Pb na água será de 2,07×101 mg/L, maior que o valor permitido.', @q), ('B', N'É segura, pois a concentração de Pb na água será de 1×10ꟷ4 mg/L, menor que o valor permitido.', @q), ('C', N'Não é segura, pois a concentração de Pb na água será de 1×10ꟷ8 mg/L, menor que o valor permitido.', @q), ('D', N'É segura, pois a concentração de Pb na água será de 1×10ꟷ2 mg/L, igual ao valor permitido.', @q), ('E', N'É segura, pois a concentração de Pb na água será de 2,07×10ꟷ6 mg/L, maior que o valor permitido. Note e adote: Massa molar (g/mol): Pb = 207', @q);
