INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'À queda de uma maçã, que teria inspirado Newton à descoberta da gravitação universal.', @q), ('B', N'À observação de um pássaro em voo, que teria levado Einstein a formular a teoria da relatividade.', @q), ('C', N'Aos experimentos com objetos de massas diferentes, que teriam indicado a Galileu os princípios da queda livre.', @q), ('D', N'Ao transbordamento da água em uma banheira, que teria sugerido a Arquimedes o conceito de empuxo.', @q), ('E', N'À queda de um bloco de ferro ligado a uma hélice, que teria levado Joule à equivalência entre calor e energia.', @q);
