INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Ao empregar o pronome se em “utilizou-se o caldo de cana em uma célula a combustível para gerar energia elétrica”, o pesquisador', NULL, N'D', 1081, N'MEDIO', 2025, 66, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 66 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Língua Portuguesa'));
