INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A reação do antibiótico sulfanilamida com halogênios leva à reação de substituição com o halogênio em duas posições distintas do anel aromático, como representado na equação não balanceada a seguir.
Em um experimento, 1 L de uma solução de sulfanilamida de pH 5 reagiu com Br2 em excesso, obtendo-se pH 4 após reação total. Considerando que o volume se manteve inalterado após a adição do halogênio, quantos mols de sulfanilamida reagiram com bromo?', NULL, N'A', 1128, N'DIFICIL', 2025, 72, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 72 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
