INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia o excerto a seguir de A Ética Protestante e o Espírito do Capitalismo, de Max Weber.
“Temos de nos emancipar da seguinte visão: que se pode deduzir a Reforma das transformações econômicas como algo ‘necessário em termos de desenvolvimento histórico’. Por outro lado, não se deve de forma alguma defender uma tese tão disparatadamente doutrinária que afirmasse que o ‘espírito capitalista’ pôde surgir somente como resultado de determinados influxos da Reforma.
Em face da enorme barafunda de influxos recíprocos entre as bases materiais, as formas de organização social e política e o conteúdo espiritual das épocas culturais da Reforma, procederemos tão-só de modo a examinar de perto se, e em quais pontos, podemos reconhecer determinadas ‘afinidades eletivas’ entre certas formas da fé religiosa e certas formas da ética profissional. Por esse meio serão elucidados o efeito que, em virtude de tais afinidades eletivas, o movimento religioso exerceu sobre o desenvolvimento da cultura material.”
WEBER, Max. A Ética Protestante e o Espírito do Capitalismo. São Paulo: Companhia das Letras, 2004, p.82-83 (Adaptado).
A partir da ideia expressa no excerto acerca da relação entre o desenvolvimento do capitalismo e alguns elementos da doutrina calvinista, é correto afirmar que', NULL, N'E', 1104, N'MEDIO', 2025, 80, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 80 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'as ideias calvinistas impulsionaram o capitalismo e levaram os comerciantes germânicos a buscar a acumulação irrestrita de capitais.', @q), ('B', N'o crescimento acelerado dos mercados consumidores facilitou, no século XVI, a aceitação das ideias calvinistas pelos banqueiros e negociantes europeus.', @q), ('C', N'as condições materiais, sociais e políticas da Europa Central contribuíram, no século XVI, para a expansão do capitalismo e para a repressão do calvinismo.', @q), ('D', N'a união entre os comerciantes contra o Sacro Império Romano Germânico e contra o Papado determinou a adoção de práticas capitalistas e calvinistas na Europa medieval.', @q), ('E', N'a defesa calvinista do trabalho árduo e o estímulo ao comportamento austero do crente tiveram impactos positivos na formação de condutas adequadas ao desenvolvimento do capitalismo.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Sociologia' AND t.nome = N'Trabalho e desigualdade';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“O eixo econômico do país, que já havia se deslocado para a zona de mineração, caminhou mais uma vez, deslocando-se em direção às ondulações do planalto paulista, que foram se recobrindo pelo verde escuro dos cafezais. Enquanto outras regiões brasileiras vegetavam ou iniciavam mesmo um processo de decadência econômica, a Província, logo depois estado de São Paulo, apresentava uma ascensão esplêndida e vigorosa.”
PETRONE, Pasquale. As indústrias paulistanas e os fatores de sua expansão. Terra Livre. 1953, p. 27 (Adaptado).
Sobre a industrialização no território brasileiro, é correto afirmar:

Concurso Vestibular FUVEST 2025 – Prova V1', NULL, N'D', 1095, N'MEDIO', 2025, 81, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 81 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Tal como São Paulo, a Zona Franca de Manaus teve a expansão de suas indústrias dada pelo potencial do mercado consumidor local dos produtos resultantes da industrialização.', @q), ('B', N'O Nordeste teve sua expansão industrial durante o Estado Novo, em razão da alta concentração de capitais dos estados da região, permitindo conexões dos seus polos industriais já consolidados.', @q), ('C', N'O boom industrial que aconteceu na região Sul, a partir da década de 1980, foi similar ao desenvolvimento ocorrido no Sudeste, onde a mão de obra especializada aumentou a produção.', @q), ('D', N'A concentração industrial no Sudeste ocorreu devido à existência de mercado consumidor, de capitais, de mão de obra disponível e de maior capacidade dos meios de transporte.', @q), ('E', N'A região Centro-Oeste contou com a facilidade de obtenção de energia, por meio de hidrelétricas e termoelétricas, além da densa malha viária para o seu desenvolvimento industrial.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia agrária e economia';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Mais de uma vez, o brasileiro Machado de Assis e o português Eça de Queirós foram aproximados porque traçaram linhas de compreensão das suas respectivas sociedades, em um mesmo tempo historicamente situado. Os protagonistas Rubião, de Quincas Borba (1891), e Gonçalo, de A Ilustre Casa de Ramires (1900),', NULL, N'D', 1091, N'MEDIO', 2025, 82, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 82 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Filosofia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'representam, respectivamente, a ascensão política da burguesia brasileira durante a segunda metade do século XIX e a decadência da aristocracia portuguesa no mesmo período.', @q), ('B', N'têm suas aspirações de grandeza e reconhecimento social frustradas diretamente pelo envolvimento de ambos com as políticas partidárias nacionais, introduzindo reformas substanciais que alteram a situação periférica de cada país.', @q), ('C', N'buscam reconhecimento social, continuamente frustrados nesse propósito por se inserirem em meios sociais que privilegiam a grandeza moral e as virtudes humanas.', @q), ('D', N'comprometem-se com a superação dos atrasos civilizacionais de seus países. Apesar de terem destinos diferentes, confrontam-se com o descompromisso de suas respectivas sociedades quanto às transformações sociais e econômicas.', @q), ('E', N'são vítimas de suas ideias ambiciosas de modernização nacional, seja por Rubião promover ideias políticas “modernas”, seja por Gonçalo insistir na restauração da grandeza de sua família. Ao final, atingem seus objetivos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Filosofia' AND t.nome = N'Ética e política';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia os trechos das obras Marília de Dirceu e Romanceiro da Inconfidência:
Lira VII (Parte II)
“Meu prezado Glauceste, Se fazes o conceito Que, bem que réu, abrigo A cândida Virtude no meu peito; Se julgas, digo, que mereço ainda Da tua mão socorro; Ah! Vem dar-mo agora, Agora, sim, que morro!
Não quero que, montado No Pégaso fogoso, Venhas com dura lança Ao monstro infame traspassar, raivoso. Deixa que viva a pérfida calúnia, E forje o meu tormento: Com menos, meu Glauceste, Com menos me contento.”
Tomás Antônio Gonzaga. Marília de Dirceu.
Romance LXVI ou De Outros Maldizentes
“- Que fica, na fortaleza, daquele poeta Gonzaga? - Um par de esporas, somente. Um par de esporas de prata. (...) Dizem que tinha um cavalo que Pégaso se chamava. Não pisava neste mundo, mas nos planaltos da Arcádia!”
Cecília Meireles. Romanceiro da Inconfidência.
Considerando o substantivo Pégaso, presente nos dois excertos, é correto afirmar:', NULL, N'B', 1100, N'MEDIO', 2025, 84, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 84 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Filosofia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'No poema de Cecília Meireles, a referência tem por objetivo destacar o animal mítico, enquanto na lira de Gonzaga o substantivo se refere a um animal real.', @q), ('B', N'No poema de Gonzaga, a referência ao animal mitológico serve para aludir às características heroicas de Glauceste, enquanto, no poema de Cecília Meireles, Pégaso alude à criação poética.', @q), ('C', N'Por pretender um tom épico, Cecília Meireles usa o animal mitológico para distinguir a condição heroica do poeta, enquanto Gonzaga se refere às suas diferenças com Glauceste.', @q), ('D', N'No poema de Cecília Meireles, a metáfora do cavalo alado indica a evasão da realidade, típica dos poetas árcades, enquanto, no poema de Gonzaga, a referência ao animal serve para aludir às suas próprias características heroicas.', @q), ('E', N'A referência ao cavalo alado provoca um efeito de estranhamento no leitor, tendo em vista as características específicas de cada obra poética.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Filosofia' AND t.nome = N'Ética e política';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'No texto intitulado Tarsila, a pesquisadora Aracy Amaral transcreve um trecho das impressões de Tarsila do Amaral sobre a viagem às cidades históricas coloniais mineiras, que realizara em 1924 com o grupo modernista, liderado por Mário de Andrade: “(...) As decorações murais de um modesto corredor de hotel; o forro das salas, feito de taquarinhas coloridas e trançadas; as pinturas das igrejas, simples e comoventes, executadas com amor e devoção por artistas anônimos; o Aleijadinho, nas suas estátuas e nas linhas geniais da sua arquitetura religiosa, tudo era motivo para as nossas exclamações admirativas. Encontrei em Minas as cores que adorava em criança. Ensinaram-me depois que eram feias e caipiras. Segui o ramerrão do gosto apurado... Mas depois vinguei-me da opressão passando-as para as minhas telas: azul puríssimo, rosa violáceo, amarelo vivo, verde cantante, tudo em gradações mais ou menos fortes, conforme a mistura de branco. Pintura limpa, sobretudo, sem medo de cânones convencionais. Liberdade e sinceridade, uma certa estilização que a adaptava à época moderna.”
AMARAL, Tarsila, 1939. Apud AMARAL, Aracy. Tarsila, In: Tarsila do Amaral. São Paulo: Fundação Finambras, s.d, p.4.

Tarsila do Amaral, O mamoeiro, 1925, óleo s/ tela, 65,0 cm x 70,0 cm. Coleção Mário de Andrade - Instituto de Estudos Brasileiros da Universidade
de São Paulo. Reprodução fotográfica: Rômulo Fialdini. Disponível em: https://enciclopedia.itaucultural.org.br/.
Considerando a obra O Mamoeiro, de Tarsila do Amaral, qual é o principal elemento que caracteriza a influência do movimento modernista brasileiro na pintura?', NULL, N'B', 1103, N'MEDIO', 2025, 86, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 86 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Sociologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'O emprego de recursos pictóricos que realçam os efeitos de luz e sombra na cena retratada.', @q), ('B', N'A representação de aspectos da cultura brasileira, valorizando uma paisagem local.', @q), ('C', N'A simplificação de formas geométricas abstratas.', @q), ('D', N'A inspiração na arte africana e na produção simbólica de povos originários.', @q), ('E', N'A incorporação da colagem e de técnicas mistas como procedimentos artísticos centrais.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Sociologia' AND t.nome = N'Cultura e sociedade';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Tecidos de Ijebu
“Os ijebus vestem-se quase sempre com panos produzidos por eles próprios. São fazendas de algodão, matéria-prima que obtêm localmente. Nas famílias, as tarefas de colher algodão, fiá-lo, tecê-lo e tingi-lo estão costumeiramente a cargo das mulheres, e sabe-se ser muito grande a quantidade de tecidos manufaturados em Ijebu e dali exportados, não apenas para os países vizinhos, mas até mesmo para o Brasil, cujos navios vêm buscar em Lagos essa mercadoria tão apreciada pela gente de origem africana transplantada para aquela terra distante. As cores mais comuns, depois da branca e da azul, são a amarela, a vermelha, a carmesim e a verde. Alguns panos são de uma só cor, outros são multicoloridos.”
OSIFEKUNDE. Notícia sobre o país e o povo dos Ijebus. In: COSTA E SILVA, Alberto. Imagens da África. São Paulo: Penguin, 2012. p.361.
O texto é parte de um relato das memórias de um exescravizado natural de Ijebu, na atual Nigéria, trazido ao Brasil no início do século XIX. O excerto faz menção', NULL, N'A', 1093, N'MEDIO', 2025, 87, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 87 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'à existência de um comércio de produtos manufaturados entre a África e a América.', @q), ('B', N'à prerrogativa masculina na produção de tecidos naquela região da África.', @q), ('C', N'à baixa qualidade das manufaturas africanas em comparação com as da Europa.', @q), ('D', N'à impossibilidade de acesso, por africanos e afrodescendentes, a produtos vindos da África.', @q), ('E', N'ao comércio de africanos escravizados para o trabalho nas plantações de algodão.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia agrária e economia';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“Consiste em uma faixa de terra semiárida e árida que contorna a borda sul do Deserto do Saara e percorre a extensão da África no sentido leste-oeste. Atua como um cinturão que divide o continente africano em dois, a África majoritariamente islâmica, ao norte, e a cristã, ao sul. Englobando ao menos onze países, a região é lar para dezenas de grupos étnicos.”
VAGEN, Tor-Gunnar; GUMBRICHT, Thomas. UNEP/ONU, 2012 (Adaptado).
O texto descreve características da região denominada de', NULL, N'E', 1079, N'MEDIO', 2025, 88, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 88 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
