INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia física e clima';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“Aconteceu num debate, num país europeu. Da assistência alguém me lançou a seguinte pergunta:
- Para si, o que é ser africano? Falava-se, inevitavelmente, de identidade versus globalização. Respondi com uma pergunta: - E para si, o que é ser europeu? O homem gaguejou. Não sabia responder. Mas o interessante é que, para ele, a questão da identidade se colocava naturalmente para os africanos. Não para os europeus. Ele nunca tinha colocado a questão no espelho.

Concurso Vestibular FUVEST 2025 – Prova V1
Recordo o episódio porque me parece que ele toca uma questão central: quando se fala de África, de qual África estamos falando? Terá o continente africano uma essência facilmente capturável? Haverá uma substância exótica que os caçadores de identidades possam recolher como sendo a alma africana?”
COUTO, Mia. “Um retrato sem moldura”. In: HERNANDEZ, Leila Leite. A África na sala de aula: visita à história contemporânea. São Paulo: Selo
Negro, 2008. p.11.
Ao relatar e comentar o episódio, o escritor moçambicano Mia Couto apresenta a África como', NULL, N'E', 1094, N'MEDIO', 2025, 89, 'OFICIAL', N'FUVEST 2025 - 1ª fase, Prova V1, questão 89 (gabarito oficial)', N'https://www.fuvest.br/wp-content/uploads/fuvest2025_primeira_fase_prova_V1.pdf', (SELECT id FROM Vestibular WHERE sigla = 'FUVEST'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'uma construção histórica proporcionada pela ação humanitária dos colonizadores europeus.', @q), ('B', N'um resultado natural da luta dos povos do continente contra a dominação estrangeira.', @q), ('C', N'uma região historicamente afetada por graves problemas demográficos e sanitários.', @q), ('D', N'um continente definido a partir de critérios políticos e geográficos deterministas.', @q), ('E', N'um mosaico composto por relações econômicas, políticas e culturais instáveis.', @q);
