INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'geométrica: trata-se de uma linha demarcada por formas geográficas tais como muros, cercas ou vias de circulação.', @q), ('B', N'política: trata-se de uma zona definida por meio de disputas e acordos internacionais pelo direito de uso de um determinado território.', @q), ('C', N'natural: trata-se de uma linha demarcada por meio de marcos geográficos tais como rios, mares, lagos, geleiras e montanhas.', @q), ('D', N'técnica: trata-se de uma zona definida por tratados e convenções locais que protegem a soberania do Estado-nação.', @q);
