INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'O projeto internacional DUNE (Deep Underground Neutrino Experiment) é um gigantesco experimento idealizado para o estudo de neutrinos. Para a detecção da luz emitida quando os neutrinos atravessam enormes tanques de argônio líquido, foi projetado na Unicamp um dispositivo chamado Arapuca, cuja função é aumentar a área de coleta da luz, confinando-a no interior de uma caixa que contém os sensores. Antes de entrar na Arapuca, a luz emitida, de comprimento de onda λ1 = 128 nm, incide num material que tem por finalidade modificar o comprimento de onda da radiação, de modo que, ao emergir desse material, o novo comprimento de onda da luz passe a ser λ2 = 350 nm. Considere que, nessa etapa do experimento, ambos os feixes luminosos de comprimentos de onda λ1 e λ2 propagam-se no mesmo meio. Sendo f1 a frequência e v1 a velocidade da luz no comprimento de onda λ1, e f2 a frequência e v2 a velocidade da luz no comprimento de onda λ2, pode-se afirmar que', NULL, N'B', 1141, N'DIFICIL', 2025, 11, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 11 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'a frequência f2 é maior que a frequência f1; a velocidade v2 é igual à velocidade v1.', @q), ('B', N'a frequência f2 é menor que a frequência f1; a velocidade v2 é igual à velocidade v1.', @q), ('C', N'a frequência f2 é igual à frequência f1; a velocidade v2 é maior que a velocidade v1.', @q), ('D', N'a frequência f2 é igual à frequência f1; a velocidade v2 é menor que a velocidade v1.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Ondulatória e óptica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia o texto a seguir.
Police under fire after threat to arrest ‘openly Jewish’ man near pro-Palestinian protest
Scotland Yard criticised after suggesting Gideon Falter’s presence was ‘provocative’ and he was ‘antagonising’ protesters (https://www.telegraph.co.uk/news/2024/04/19/. Acesso em 20/04/2024.)
