INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Um telefone celular custava R$ 2.000,00 em janeiro. Em abril, seu preço foi reajustado em 10%. Em junho, o preço foi novamente reajustado em 10%. Numa promoção, em novembro, Rogério finalmente comprou, com um desconto de 20%, o celular. Quanto ele pagou pelo aparelho?', NULL, N'B', 1125, N'DIFICIL', 2025, 49, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 49 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
