INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Seja (an)n∈ = (a1, a2, a3,…) uma progressão aritmética de razão r e seja (s1, s2, s3,…) a sequência definida por sn = a1 + ⋅⋅⋅ + an, isto é, o seu n-ésimo termo é a soma dos n primeiros termos da sequência (an)n∈.Sabendo que 168, 220 e 279 são termos consecutivos da sequência (sn)n∈ , a razão da progressão aritmética (an)n∈ é:', NULL, N'B', 1125, N'DIFICIL', 2025, 56, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 56 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
