INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Para a safra de 2023/2024, prevê-se uma produção de 34 bilhões de litros de etanol, com geração de 408 bilhões de litros de vinhaça, subproduto de alto teor de matéria orgânica. Nas últimas décadas, visando à sustentabilidade, o emprego da vinhaça in natura evoluiu: seu descarte direto em rios e em áreas de sacrifício deu lugar à fertirrigação direta (devido ao alto teor de potássio do subproduto). A partir de 2015, empregando biodigestores anaeróbicos, a vinhaça in natura passou a ser convertida em biogás, o qual, após purificação, é denominado gás natural renovável. Em média, 1 m3 de vinhaça produz até 14 m3 de biogás, e o subproduto desse processo é a vinhaça líquida biodigerida, que continua sendo utilizada na fertirrigação.
Em vista dessas informações, pode-se concluir que a sustentabilidade do processo de biodigestão da vinhaça in natura é devida à geração de energia renovável a partir da queima do', NULL, N'D', 1144, N'DIFICIL', 2025, 61, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 61 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'butano. Adicionalmente, a vinhaça biodigerida aplicada à fertirrigação reduz, em relação à vinhaça in natura, a demanda bioquímica de oxigênio.', @q), ('B', N'metano. Adicionalmente, a vinhaça biodigerida aplicada à fertirrigação aumenta, em relação à vinhaça in natura, a demanda bioquímica de oxigênio.', @q), ('C', N'butano. Adicionalmente, a vinhaça biodigerida aplicada à fertirrigação aumenta, em relação à vinhaça in natura, a demanda bioquímica de oxigênio.', @q), ('D', N'metano. Adicionalmente, a vinhaça biodigerida aplicada à fertirrigação reduz, em relação à vinhaça in natura, a demanda bioquímica de oxigênio.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Matemática' AND t.nome = N'Estatística';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Os submarinos nucleares conseguem submergir por longos períodos, pois geram uma quantidade enorme de energia elétrica para ser usada internamente. Um dos desafios a serem enfrentados diz respeito à manutenção da atmosfera interna da embarcação, o que garantiria condições respiráveis. Para tanto, controlam-se as concentrações de oxigênio e gás carbônico. Em vista dessa descrição, você, como responsável por essa manutenção, sugeriria a combinação das seguintes ações:', NULL, N'B', 1138, N'DIFICIL', 2025, 62, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 62 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'para gerar O2: destilação direta da água do mar; para absorver o CO2: uso de uma solução ácida. Percentual de energia proteínas gorduras carboidratos 5% 52% 43%', @q), ('B', N'para gerar O2: eletrólise da água purificada do mar; para absorver o CO2: uso de uma solução básica. A partir dessas informações, pode-se afirmar que, em comparação com os respectivos percentuais em energia, os percentuais em massa de', @q), ('C', N'para gerar O2: destilação da água purificada do mar; para absorver o CO2: uso de uma solução básica. Concentração de DMSO (mol/L) Efeito Repelente Efeito Inseticida', @q), ('D', N'para gerar O2: eletrólise direta da água do mar; para absorver o CO2: uso de uma solução ácida.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Estequiometria e soluções';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A bula do medicamento genérico “cloridrato de venlafaxina” informa apresentações de cápsulas de liberação controlada, cada uma contendo 42,4 mg dessa substância, o que corresponde a 37,5 mg de venlafaxina neutra. O cloridrato de venlafaxina corresponde à molécula venlafaxina neutra associada ao HCl. Isso confere ao cloridrato de venlafaxina uma massa molar e uma solubilidade maiores em água (quando comparado com a venlafaxina neutra). Considerando essas informações, pode-se afirmar que a cada molécula de venlafaxina neutra se associa(m)
Dado: massa molar do HCl = 36,5 g/mol.', NULL, N'B', 1136, N'DIFICIL', 2025, 63, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 63 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Química'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'uma molécula de HCl, então a massa molar da venlafaxina neutra é de aproximadamente 140 g/mol.', @q), ('B', N'uma molécula de HCl, então a massa molar da venlafaxina neutra é de aproximadamente 279 g/mol.', @q), ('C', N'duas moléculas de HCl, então a massa molar da venlafaxina neutra é de aproximadamente 279 g/mol.', @q), ('D', N'duas moléculas de HCl, então a massa molar da venlafaxina neutra é de aproximadamente 140 g/mol.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Química' AND t.nome = N'Estequiometria e soluções';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Considera-se que a evolução cria e sustenta a biodiversidade via mudanças adaptativas em características ecologicamente relevantes. A especiação é um processo contínuo que dá origem à diversidade biológica, e está intimamente associada a mudanças no fenótipo e à adaptação ao ambiente ecológico.
Assinale a alternativa correta.', NULL, N'B', 1084, N'MEDIO', 2025, 70, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 70 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'A deriva genética é um componente da especiação, levando a uma maior diversidade genética devido ao fluxo de genes entre populações.', @q), ('B', N'A seleção natural contribui para a adaptação ecológica tanto na presença como na ausência de isolamento geográfico entre populações.', @q), ('C', N'A especiação é induzida por barreiras de fluxo gênico entre populações, sendo resultante da seleção convergente baseada na ecologia entre ambientes.', @q), ('D', N'O isolamento geográfico é necessário para que ocorra a especiação, com as novas espécies ocupando nichos ecológicos distintos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Estima-se que mais de dois milhões de espécies habitem os oceanos; entretanto, somente 10% da vida oceânica é conhecida. Em janeiro de 2024, uma expedição na costa do Chile avaliou um trecho de 2.900 km2 de montanhas subaquáticas criadas por atividade vulcânica, o que resultou em uma região única com correntes marítimas e baixo teor de oxigênio, gerando um nível elevado de endemismo.
Em menos de um mês, a expedição documentou cem novas espécies animais de profundidade, incluindo corais, esponjas, lagostas, polvos, caravelas, águas-vivas, peixes, camarões, entre outros.
(Adaptado de https://www.nytimes.com/2024/03/10/science/new-species-sea-discove ry.html. Acesso em 02/04/2024.)
Sobre essa expedição marinha, é correto afirmar que os animais', NULL, N'B', 1143, N'DIFICIL', 2025, 71, 'OFICIAL', N'Unicamp 2025 - 1ª fase, Prova Q, questão 71 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2025/F1/f12025Q_Z.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'são encontrados em diversos locais do planeta Terra e que os peixes e as caravelas são exemplos de animais triblásticos.', @q), ('B', N'encontrados têm distribuição restrita no planeta Terra, e que as águas-vivas e os corais possuem simetria radial, tecidos verdadeiros e se reproduzem de forma sexuada e assexuada.', @q), ('C', N'são encontrados em diversos locais do planeta Terra e que os camarões e as lagostas são exemplos de animais diblásticos.', @q), ('D', N'encontrados têm distribuição restrita no planeta Terra e que os polvos representam o estágio de vida medusoide, estado este caracterizado pelo formato de sino, boca voltada para baixo e presença de tentáculos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Eletricidade e magnetismo';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia a carta a seguir.
Dear Members of the Harvard Community, For years, the federal government’s grants to Harvard have helped lead to groundbreaking innovations. Recently, the federal government has threatened its partnerships over accusations
of antisemitism on our campuses. A list of demands was issued, warning that Harvard must comply if we intend to “maintain our financial relationship with the government.” Most of these demands are unprecedented and represent direct governmental regulation of the “intellectual conditions” at Harvard. They include requirements to audit the viewpoints of our students and faculty, and to “reduce their power” for their ideological views. We will not accept that. The University will not surrender its independence or relinquish its constitutional rights. No government should dictate what universities can teach and which areas of inquiry they can pursue. We do not take our moral duties lightly and we have taken many steps to address and fight antisemitism on campus. However, this will not be achieved by assertions of power, unmoored from the law, to dictate how we operate.
Sincerely,
Alan M. Garber (President of Harvard University)
(Adaptado de https://www.harvard.edu/president/news/2025/the-promise-of-american-higher-education/. Acesso em 07/05/2025.)
Assinale a alternativa correta em relação ao posicionamento do presidente de Harvard em sua carta.', NULL, N'D', 1160, N'DIFICIL', 2026, 7, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 7 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'As acusações de antissemitismo feitas à universidade são inconstitucionais, por isso Garber se recusa a aceitar as demandas propostas pelo governo.', @q), ('B', N'As comparações entre as ideologias de professores e de alunos são sem precedentes, por isso Garber se nega a abrir mão da liberdade de expressão da comunidade.', @q), ('C', N'As justificativas do governo para interromper o financiamento são falhas, por isso Garber se nega a tomar medidas para resolver os problemas apontados.', @q), ('D', N'As demandas do governo são uma tentativa de controle da autonomia das universidades, por isso Garber se recusa a acatar as exigências impostas. Texto para as questões 9, 10 e 11. As baterias são fundamentais no mundo moderno, sendo a fonte de energia portátil que alimenta dispositivos como celulares e laptops, veículos elétricos e sistemas de armazenamento de energia renovável. Duas grandezas que caracterizam uma bateria é a sua capacidade de carga elétrica, expressa em miliampère-hora (mAh) e a energia que ela armazena, usualmente dada em watts-hora (Wh).', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Eletricidade e magnetismo';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'“O ato de comer é construído culturalmente, e mediado por práticas, crenças, comportamentos, tabus, que formam os hábitos alimentares, que, por sua vez, relacionam-se a aspectos culturais, socioeconômicos e psicológicos que envolvem o ambiente alimentar de cada indivíduo. Os hábitos alimentares são dinâmicos e sensíveis às mudanças que ocorrem nas sociedades, fundamentalmente, nos sistemas alimentares. Com o sistema alimentar que predomina hoje, a humanidade vem substituindo a comida que carrega significados culturais e tradições ancestrais por produtos alimentares ultraprocessados globalizados, que viajam quilômetros até chegar ao prato, causando a homogeneização dos hábitos alimentares de forma global. O problema é que os ultraprocessados têm acarretado sérios problemas à saúde da população [...]”.
(Disponível em https://obha.fiocruz.br/?p=1413. Acesso em 06/08/25.)
A partir do texto, é correto afirmar que a produção e o consumo de alimentos no mundo contemporâneo possuem', NULL, N'A', 1109, N'MEDIO', 2026, 15, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 15 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Geografia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'menor vínculo com o lugar, visto que a indústria de processamento de alimentos e a produção agropecuária estão cada vez mais especializadas. Assim, produtos circulam com maior velocidade e eficiência entre a área de produção e o mercado consumidor, reduzindo o acesso da população a alimentos in natura e à diversidade produtiva regional.', @q), ('B', N'maior interdependência com o lugar, visto que a indústria de processamento precisa manter a proximidade com as áreas da produção agropecuária, aproveitando a modernização do sistema de circulação para atingir o mercado consumidor mais distante. Isso fortalece o acesso da população a produtos da agricultura familiar e à diversidade produtiva regional.', @q), ('C', N'maior conexão com o lugar, visto que a indústria de processamento de alimentos pode estar distante da área de produção agropecuária. O sistema de circulação permite interligar, com menor custo, a área de produção ao mercado consumidor, restringindo o acesso da população à produção da pequena indústria local e à diversidade alimentar regional.', @q), ('D', N'menor correlação com o lugar, visto que a indústria de processamento e a produção agropecuária possuem pouca vinculação entre si, tornando-se independentes, mas com estreitamento promovido pelo sistema de circulação entre a área de produção e o mercado consumidor. Isso favorece o acesso da população aos alimentos da culinária local e à diversidade alimentar regional.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Geografia' AND t.nome = N'Geografia agrária e economia';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia os textos 1 e 2.
Texto 1 A adolescência é uma questão de corporificação do social. Mudanças físicas, como hormônios em ebulição, são importantes, mas elas não determinam como se experimenta a adolescência. Essa é uma questão de como as práticas sociais se relacionam com as mudanças físicas, dando significados sociais a eventos biológicos. A adolescência é um processo de se tornar participante do mundo adulto. Ela é um período em que corpos em desenvolvimento enfrentam desafios, e às vezes são danificados. Instituições, incluindo a escola, e os poderes do mundo adulto são confrontados e negociados. Isso forma uma arena de prazer, humor, curiosidade, mas também de ansiedade e violência.
(Adaptado de CONNELL, R. Crescer como masculino. In: Gênero em termos reais. São Paulo: nVersos, p. 139-141, 2016.)
Texto 2 Ordens de gênero são centrais para a vida dos adolescentes.
Quando insistem na diferença absoluta entre masculinidade e feminilidade criam um dilema e fazem com que os meninos exagerem na performance da masculinidade, procurando se aproximarem da posição social dos homens adultos. Práticas corporais, como a sexualidade e o esporte, se tornam importantes meios de diferenciação e espaços de produção das masculinidades hegemônicas e subordinadas. Aquelas que produzem maior status e prestígio masculino são as com os efeitos mais tóxicos sobre os corpos dos adolescentes, como por exemplo o hábito de fumar e praticar a violência física, etc.
(Adaptado de CONNELL, R. Crescer como masculino. In: Gênero em termos reais. São Paulo: nVersos, p. 139-151, 2016.)
A partir da leitura dos textos é correto afirmar que', NULL, N'C', 1110, N'DIFICIL', 2026, 24, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 24 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Artes e Educação Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'a adolescência, como processo de participar do mundo adulto, desafia padrões previamente estabelecidos, promovendo riscos e violência que poderiam ser evitados caso tais padrões fossem mantidos.', @q), ('B', N'masculinidades hegemônicas e subordinadas são produzidas biológica e socialmente, por meio de práticas corporais como a sexualidade e o esporte e em confronto com instituições, como a escola.', @q), ('C', N'eventos biológicos associados às mudanças corporais da adolescência são significados socialmente, o que torna a ordem de gênero em que tais mudanças ocorrem importante para compreendermos masculinidades e feminilidades.', @q), ('D', N'a precocidade na busca de status de adultos e do prestígio masculino por meninos adolescentes os torna ansiosos, fazendo das masculinidades juvenis contemporâneas um todo homogêneo e violento.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Artes e Educação Física' AND t.nome = N'Corpo, esporte e saúde';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'A OMS, e não uma associação trans-gay-lésbica-anarcofeminista, afirma hoje que “o gênero tipicamente descrito como masculino e feminino é uma construção social que varia segundo as culturas e épocas”. A partir desse princípio, a OMS reconhece a dimensão arbitrária e inatural da taxonomia binária com a qual as instituições sociais e políticas trabalham no Ocidente e abre a porta para uma revisão mais profunda do paradigma da diferença sexual. Nos próximos anos, deveremos elaborar coletivamente uma epistemologia capaz de dar conta da multiplicidade radical dos seres vivos, que não reduza o corpo à sua força reprodutiva heterossexual, que não legitime a violência heteropatriarcal e colonial. Quando falo de uma nova epistemologia me refiro também a um processo de ampliação radical do horizonte democrático para reconhecer como sujeito político todo corpo vivo sem que a designação sexual ou de gênero seja a condição desse reconhecimento social e político (84).
(Adaptado de PRECIADO, P. Eu sou o monstro que vos fala. Zahar Editora, p. 78-84, 2022.)
Considerando o texto assinale a alternativa correta.', NULL, N'C', 1102, N'MEDIO', 2026, 25, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 25 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'A diferença sexual entre homem e mulher é informada pela biologia e indiferente a variações culturais, a despeito do que dizem a OMS e as associações feministas, gays, lésbicas e trans.', @q), ('B', N'Embora seja inevitável admitir que haja pessoas que não se enquadram na taxonomia binária, é necessário elaborar coletivamente caminhos para ajudá-las a uma reconciliação com a própria natureza.', @q), ('C', N'As instituições sociais e políticas operam normalmente com uma taxonomia binária violenta e excludente da multiplicidade de seres humanos, que precisa ser revista em nome da ampliação do nosso horizonte democrático.', @q), ('D', N'Gênero e sexualidade são categorias identitárias inadequadas ao processo de ampliação do horizonte democrático com vistas ao reconhecimento social e político de todos os indivíduos em função do seu próprio mérito.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'Brasil Colônia e Império';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Leia os textos 1 e 2.
Texto 1 "Para Rosa Luxemburgo, uma sociedade socialista terá necessariamente que ser democrática (e vice-versa), o que significa que só poderá resultar da participação efetiva das massas populares. [...] ela rejeita premonitoriamente a estratégia dos partidos de esquerda que chegarão ao poder no decorrer do século XX: primeiro toma-se o poder, depois muda-se o mundo. Para ela, a tomada do poder e a instituição da democracia (equivalente aqui à mudança do mundo) não são duas etapas separadas no tempo, mas duas faces da mesma moeda”.
(Comentário de Isabel Loureiro ao texto “A Revolução Russa (1918)” de Rosa Luxemburgo. LUXEMBURGO, R. Textos Escolhidos. Editora Expressão Popular, p. 101-2, 2009. Org. Isabel Loureiro.)
Texto 2 "Sem eleições gerais, sem liberdade ilimitada de imprensa e de reunião, sem livre debate de opiniões, a vida se definha em qualquer instituição pública, torna-se uma vida aparente em que só a burocracia subsiste como o único elemento ativo. [...] Somente massas esclarecidas, autônomas, politicamente formadas poderão exercer o poder nos novos organismos de base, os conselhos; em outras palavras, realizar o socialismo democrático".
(LUXEMBURGO, R. Textos Escolhidos. A Revolução Russa (1918). Editora Expressão Popular, Org. Isabel Loureiro, p. 114-131, 2009.)
Considerando os textos, assinale a alternativa que corresponde ao pensamento de Rosa Luxemburgo.', NULL, N'D', 1153, N'DIFICIL', 2026, 26, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 26 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'Para afastar o socialismo da ameaça da burocracia, às vezes é necessário restringir a liberdade de imprensa, o debate público e as eleições gerais.', @q), ('B', N'A instituição da democracia é uma etapa posterior à tomada do poder político e equivale à mudança do mundo.', @q), ('C', N'A democracia socialista não difere da democracia representativa: ambas se baseiam na soberania popular dos conselhos, mas tendem à burocracia partidária.', @q), ('D', N'Democracia e socialismo são sinônimos, pois os conselhos populares deveriam possibilitar a participação ativa das massas na condução do poder político e econômico.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Ondulatória e óptica';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Entre várias obras que devem formar este precioso presente que ofereço aos meus concidadãos, dei o primeiro lugar ao Contrato Social, escrito pelo cidadão de Genebra, Jean-Jacques Rousseau. Este homem imortal, que obteve a admiração de seu século e será o assombro de todas as idades, [... ensinou que] os povos aprenderam a procurar no pacto social a raiz e a única origem da obediência, não reconhecendo os seus chefes como emissários da divindade, enquanto não mostrassem as patentes do céu na qual eram destinados a imperar sobre seus semelhantes. [...] Como o autor teve a desgraça de delirar em matérias religiosas, suprimo o capítulo e as passagens principais onde delas tratou.
(MORENO, M. Prólogo de O Contrato Social ou Princípios do direito político, de Jean-Jacques Rousseau, Buenos Aires, 1810 apud MYERS, J. A revolução de independência no Rio da Prata e as origens da nacionalidade argentina (1806-1825) In: PAMPLONA, M; MÄDER, M. (org.). Revoluções de independências e nacionalismos nas Américas: região do Prata e Chile. São Paulo: Paz e Terra, p. 107 e 109, 2007.)
Mariano Moreno, tradutor de Rousseau para o espanhol, foi secretário do primeiro governo da Argentina entre os anos 1810 e 1811. No texto acima, ele', NULL, N'B', 1097, N'MEDIO', 2026, 30, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 30 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'História'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'critica a defesa que Rousseau faz da Igreja e dos governos absolutistas na obra O Contrato Social.', @q), ('B', N'interfere na tradução e edição da obra de Rousseau conforme seus ideários políticos e ideológicos.', @q), ('C', N'justifica a tradução da obra para difundir a ideia de obediência cívica ligada à religião católica e ao rei.', @q), ('D', N'demonstra seu caráter conservador e a resistência ao pensamento liberal e iluminista na Argentina.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'História' AND t.nome = N'História antiga e medieval';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Um agricultor realizou a remoção de um anel da casca de ramos caulinares, prática conhecida como anelamento, para aumentar o tamanho dos frutos em seu pomar. Ele observou dois grupos de plantas após algumas semanas. As plantas do grupo 1 tinham uma região claramente anelada nos ramos e seus frutos eram maiores, se comparadas às plantas do grupo 2. Já as plantas do grupo 2 perderam as folhas e foram claramente prejudicadas pelo anelamento. Ao retornar no ano seguinte, o anelamento era quase imperceptível nas plantas do grupo 1.
Considerando as informações apresentadas e os seus conhecimentos em biologia vegetal, é correto afirmar que o anelamento eliminou os vasos do

350 kg

500 kg

150 kg

Considerando as informações apresentadas, assinale a alternativa correta.', NULL, N'D', 1093, N'MEDIO', 2026, 36, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 36 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'A heterose ocorre no cruzamento entre indivíduos heterozigotos, levando à maior massa corporal, com probabilidade de ocorrer em 66% dos animais da geração F1.', @q), ('B', N'A heterozigose tem probabilidade de ocorrer em 33% dos animais da geração F1, proporcionando animais com maior massa corporal e maior variabilidade genética.', @q), ('C', N'A depressão endogâmica tem probabilidade de ocorrer em 25% dos animais da geração F1, proporcionando animais com menor massa corporal e também menor variabilidade genética.', @q), ('D', N'A homozigose determina a depressão endogâmica, levando à menor massa corporal, com probabilidade de ocorrer em 50% dos animais da geração F1.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Genética e evolução';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Considere a placa de aviso encontrada em uma reserva ecológica.
CUIDADO, INSETOS PERIGOSOS!

MOSQUITOS

CARRAPATOS

ESCORPIÕES

ABELHAS

(Adaptado de https://pt.dreamstime.com. Acesso em 31/03/2025.)
A informação da placa está', NULL, N'D', 1082, N'MEDIO', 2026, 40, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 40 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Biologia'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'correta, já que os carrapatos e escorpiões são classificados como quilópodes e os mosquitos e as abelhas como diplópodes.', @q), ('B', N'errada, pois apenas dois animais são artrópodes, sendo eles os mosquitos e as abelhas, que são classificados como insetos.', @q), ('C', N'correta, já que os mosquitos e as abelhas são classificados como artrópodes e os carrapatos e escorpiões como aracnídeos.', @q), ('D', N'errada, pois mesmo que todos os animais sejam classificados como artrópodes, os carrapatos e os escorpiões são aracnídeos.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Biologia' AND t.nome = N'Ecologia e meio ambiente';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Rogério é funcionário de uma fábrica de automóveis. Em dezembro de 2024, seu gestor fez duas propostas de aumento salarial:
• a proposta 1 consistia em um aumento de 50% do seu salário, a partir do salário a ser recebido em janeiro de 2025, mas sem nenhum tipo de reajuste nos próximos três anos, ou seja, até dezembro de 2027;
• a proposta 2 consistia em um aumento de 20% a cada ano; o reajuste ocorreria no salário de janeiro de cada um dos próximos três anos, a partir de 2025.
Para decidir a qual proposta aderir, Rogério calculou o montante total que receberia ao longo dos três anos em cada proposta, isto é, de janeiro de 2025 a dezembro de 2027. Ele concluiu que o total a ser recebido na proposta 1 é, aproximadamente,', NULL, N'A', 1135, N'DIFICIL', 2026, 43, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 43 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'3% maior que o total a ser recebido na proposta 2.', @q), ('B', N'1% maior que o total a ser recebido na proposta 2.', @q), ('C', N'3% menor que o total a ser recebido na proposta 2.', @q), ('D', N'1% menor que o total a ser recebido na proposta 2.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Matemática' AND t.nome = N'Porcentagem e matemática financeira';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Em uma creche se realiza o “dia da troca do brinquedo”. Cada criança leva um brinquedo para a escola e o guarda na Caixa Divertida. Ao final do dia, cada criança retira um brinquedo da Caixa Divertida sem olhar, e o leva para brincar em casa. Em uma sala com cinco crianças, qual é a probabilidade de exatamente duas crianças retirarem da Caixa Divertida seus próprios brinquedos?', NULL, N'B', 1126, N'DIFICIL', 2026, 49, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 49 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'1/5.', @q), ('B', N'1/6.', @q), ('C', N'1/25.', @q), ('D', N'1/30.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Matemática' AND t.nome = N'Probabilidade e análise combinatória';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Em um jogo de videogame sobre guerra, cada jogador deve montar sua tropa escolhendo 100 combatentes. Ele tem à sua disposição dois tipos de combatentes, soldados e estrategistas, que possuem duas habilidades, astúcia e força, com as seguintes pontuações:
• o soldado tem 30 pontos de astúcia e 70 pontos de força.
• o estrategista tem 80 pontos de astúcia e 20 pontos de força. A força total da tropa é a soma das pontuações de força de cada um dos combatentes, e a astúcia total da tropa é a soma das pontuações de astúcia de cada um dos combatentes.
Para montar uma tropa de modo a obter as mesmas pontuações de força total e de astúcia total, quantos soldados e quantos estrategistas devem ser escolhidos?', NULL, N'B', 1133, N'DIFICIL', 2026, 52, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 52 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Física'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'70 soldados e 30 estrategistas.', @q), ('B', N'60 soldados e 40 estrategistas.', @q), ('C', N'50 soldados e 50 estrategistas.', @q), ('D', N'40 soldados e 60 estrategistas.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Física' AND t.nome = N'Mecânica e movimento';
INSERT INTO Questao (enunciado, introducao_alternativas, gabarito, dificuldade, nivel, ano, numero, origem, fonte_descricao, fonte_url, vestibular_id, disciplina_id) VALUES (N'Em seu ensaio “A vida não é útil”, Ailton Krenak elege Carlos Drummond de Andrade como um de seus “escudos”. Ele cita a última estrofe de “O Homem; as Viagens”, poema publicado em As impurezas do Branco (1973). Reproduzimos, a seguir, a primeira e a segunda estrofe desse poema:
“O Homem; as Viagens
O homem, bicho da Terra tão pequeno chateia-se na Terra lugar de muita miséria e pouca diversão, faz um foguete, uma cápsula, um módulo toca para a Lua desce cauteloso na Lua pisa na Lua planta bandeirola na Lua experimenta a Lua coloniza a Lua civiliza a Lua humaniza a Lua.
Lua humanizada: tão igual à Terra. O homem chateia-se na Lua. Vamos para Marte – ordena a suas máquinas. Elas obedecem, o homem desce em Marte pisa em Marte experimenta coloniza civiliza humaniza Marte com engenho e arte.
Marte humanizado, que lugar quadrado. (...)”.
(ANDRADE, C. D. O Homem; As viagens, As impurezas do Branco. In: Poesia Completa. Rio de Janeiro, Editora Nova Aguilar, p. 718, 2002.) (KRENAK, A. A vida não é útil. Pesquisa e organização de Rita Carelli. São Paulo: Companhia das Letras, 2020.)
Em relação às reflexões de Ailton Krenak, é correto afirmar que esse trecho do poema', NULL, N'B', 1147, N'DIFICIL', 2026, 60, 'OFICIAL', N'Unicamp 2026 - 1ª fase, Prova Q, questão 60 (gabarito oficial Comvest)', N'https://www.comvest.unicamp.br/vest2026/F1/f12026Q_X.pdf', (SELECT id FROM Vestibular WHERE sigla = 'UNICAMP'), (SELECT id FROM Disciplina WHERE nome = N'Matemática'));
SET @q = SCOPE_IDENTITY();
INSERT INTO Alternativa (letra, texto, questao_id) VALUES ('A', N'responsabiliza a ciência e tecnologia, desgastadas em seus valores, pela corrosão das relações nas sociedades contemporâneas.', @q), ('B', N'mostra que os Homens, guiados pela ideia de progresso, não adotam uma postura consciente em relação ao seu espaço.', @q), ('C', N'evidencia que a Terra, desgastada em seus valores, foi superada pelos elementos da conquista espacial.', @q), ('D', N'identifica a aniquilação das sociedades contemporâneas nos programas de governos persuadidos pelo progresso.', @q);
INSERT INTO QuestaoTopico (questao_id, topico_id) SELECT @q, t.id FROM Topico t JOIN Disciplina d ON d.id = t.disciplina_id WHERE d.nome = N'Matemática' AND t.nome = N'Estatística';
